WITH payload AS (SELECT $archive_payload$[{"id":"549db800-2484-5aca-8199-6bcded591560","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي حشيش -إقرار -حد املسكر -حيازة املدعى عليه لسجائر اشتراها على مظنة أنها ممزوجة باحلشيش املخدر -أخذ","document_number":"34329233","case_number":"34429612","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/13","year":"1434","subject":"مخدرات -تعاطي حشيش -إقرار -حد املسكر -حيازة املدعى عليه لسجائر اشتراها على مظنة أنها ممزوجة باحلشيش املخدر -أخذ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34329233 :‬تاريخه‪1434/10/13 :‬هـ‬\n                         ‫رقم الدعوى‪34429612 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n              ‫‪     34372665‬تاريخه‪1434/11/27 :‬هـ‬\n\n\n\n      ‫مخــدرات‪ -‬تعاطــي حشــيش‪ -‬إقــرار ‪ -‬حــد املســكر ‪ -‬حيــازة املدعــى عليــه‬\n      ‫لســجائر اشــتراها علــى مظنــة أنهــا ممزوجــة باحلشــيش املخــدر‪ -‬أخــذ‬\n                                                                   ‫عليــه تعهــد‪.‬‬\n\n\n\n\n      ‫‪ .1‬مــا تقــرر عنــدا الفقهــاء بأنــه ال عبــرة بالظــن البــن خطــؤه‪ ،‬وأن‬\n      ‫الظــن إذا كان كاذبـ ًا فــا أثــر لــه‪ .‬ينظــر ‪ :‬األشــباه والنظائــر للســبكي‪:‬‬\n      ‫(‪ ،)243/1‬واملنثــور للزكشــي‪ ،)353/2( :‬واألشــباه والنظائــر للســيوطي‪:‬‬\n        ‫(‪ ،)157/1‬وغمــز عيــون البصائــر شــرح األشــباه والنظائــر‪.)460/1( :‬‬\n                     ‫‪ .2‬قاعدة العبرة مبا يف نفس األمر ال مبا يف ظن املكلف‪.‬‬\n                ‫‪ .3‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليه بتعاطيه احلشــيش املخــدر وحيازة‬\n      ‫ثــاث ســجائر يعتقــد أنهــا ممزوجــة مبــادة احلشــيش املخــدر وطلــب‬\n      ‫املدعــي العــام احلكــم عليــه بالســجن واملنــع مــن دخــول اململكــة وفــق‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬واحلكــم عليــه بعقوبــة‬\n      ‫تعزيريــة لقــاء حيازتــه مــا يعتقــد أنهــا مخــدرات‪ ،‬بعــرض دعــوى املدعــي‬\n      ‫العــام علــى املدعــى عليــه صــادق علــى حيازتــه ثــاث ســجائر يعتقــد أنهــا‬\n\n‫‪211‬‬\n\f‫ممزوجــة باحلشــيش مــن ضمــن ســتة ســجائر وأن قصــده االســتعمال‪،‬‬\n‫وقــرر أنــه ســبق وأن تعاطــى احلشــيش وأنــه تائــب ونــادم ‪ ،‬نظــر ًا ألن‬\n‫املدعــى عليــه صــادق علــى دعــوى املدعــي العــام بتعاطــي احلشــيش‬\n‫املخــدر وأقــر بحيــازة ســت ســجائر  يعتقــد أن ثالثــة منهــا ممزوجــة مبــادة‬\n‫احلشــيش املخــدر وقــد أثبــت التقريــر املخبــري ســلبية مســتخلص العينــة‬\n‫ألي مــادة مشــتبهة ومبــا أن العبــرة مبــا يف نفــس األمــر ال مبــا يف ظــن‬\n‫املكلــف لــذا فقــد ثبتــت إدانــة املدعــى عليــه بتعاطــي احلشــيش املخــدر‬\n‫ومت احلكــم عليــه بحــد املســكر بجلــده ثمانــن جلــدة علنــا‪ ،‬كمــا ثبتت‬\n‫إدانــة املدعــى عليــه بحيــازة ســت ســجائر عاديــة بقصــد االســتعمال ثالث‬\n‫منهــا يعتقــد أنهــا ممزوجــة باحلشــيش ومت احلكــم عليــه لقــاء ذلــك بأخــذ‬\n‫التعهــد عليــه بعــدم العــودة ملثــل ذلــك مســتقبالً‪ ،‬واحلكــم بإبعــاد املدعــى‬\n‫عليــه خــارج البــاد‪ ،‬وصــرف النظــر عــن طلــب املدعــي معاقبــة املدعــى‬\n‫عليــه وفــق املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات‪ ،‬بعــرض احلكــم‬\n‫علــى الطرفــن قــررا جميع ـ ًا االعتــراض عليــه بــدون الئحــة‪ ،‬وبعــد رفــع‬\n                         ‫احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة العامــة‬\n‫بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم ‪ 34429612‬وتاريــخ ‪1434/09/17‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 342208967‬وتاريخ‪1434/9/17‬ه ـ ففــي يــوم‬\n‫اإلثنــن املوافق‪1434/10/12‬ه ـ افتتحــت اجللســة  وفيهــا حضــر املدعــي‬\n‫العــام‪ ....‬وقــد الئحتــه العامــة ضــد ‪ ....‬كويتــي اجلنســية مبوجــب اجلــواز‬\n\n                                                                                      ‫‪212‬‬\n\f      ‫رقــم…‪ .‬والصــادر مــن دولــة الكويــت والتــي جــاء فيهــا مــا نصــه‪( :‬بتاريــخ‬\n      ‫‪1434/8/16‬ه ــأثناء قيــام دوريــة أمــن الطــرق بعملهــا املعتــاد علــى طريــق‬\n      ‫القريــات‪ ،‬عرعــر مت االشــتباه بســيارة مــن نــوع فــورد مــا ســنتج حتمــل‬\n      ‫اللوحــة كويتيــة رقــم (‪ ).....‬وبهــا شــخصني وباســتيقاف الســيارة اتضــح‬\n      ‫أن الســائق يدعــى ‪ ....‬كويتــي اجلنســية مبوجــب اجلــواز رقــم (‪( )....‬لــم‬\n      ‫يوجــه لــه االتهــام بشــيء) ‪ ،‬والراكــب املتهــم ‪ ......‬كويتــي اجلنســية‬\n      ‫مبوجــب اجلــواز رقــم (‪ ، )....‬ولوحــظ عليــه االرتبــاك وبتفتيــش الســيارة‬\n      ‫عثــر يف الــدرج األمامــي علــى علبــة ســجائر بهــا ســت ســجائر ثالثــة منهــا‬\n      ‫ممزوجــة مبــادة احلشــيش املخــدر بلــغ وزنهــا (‪ )1.3‬جــرام ‪    .‬وباســتجواب‬\n      ‫املتهــم ‪  ......‬أقــر بصحــة واقعــة الضبــط وبحيازتــه للســجائر املمزوجــة‬\n      ‫مبــادة احلشــيش املخــدر‪ ،‬وأن القصــد مــن احليــازة االســتعمال الشــخصي‬\n      ‫وأنــه حصــل عليهــا مــن شــخص يف مدينــة القريات وأنه يتعاطى احلشــيش‬\n      ‫املخــدر ‪ ،‬وأن مرافقــه ليــس لــه عالقــة مبــا مت ضبطــه‪    .‬وقــد أثبــت‬\n      ‫التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز الســموم بتبــوك‬\n      ‫رقــم (‪2450‬م‪/‬م س ت) لعــام ‪1434‬ه ـ ســلبية مســتخلص العينــة ألي مــادة‬\n      ‫مشــتبهة وقــد انتهــى التحقيــق إلــى اتهــام ‪ ....‬بتعاطــي احلشــيش املخــدر‬\n      ‫وحيــازة ثــاث ســجائر يعتقــد انهــا ممزوجــة مبــادة احلشــيش املخــدر‬\n      ‫املجــرم بنــص املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة ‪ .‬وحيــث أن مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫شــرعا فعــل محــرم ومعاقــب عليــه شــرعا ومجــرم نظامــا بنــص املــادة‬\n      ‫الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬الصــادر‬\n      ‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ لــذا أطلــب إثبــات‬\n                                             ‫مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪:‬‬\n\n\n‫‪213‬‬\n\f‫‪ .1‬عقوبــة الســجن وفقــا للفقــرة األولــى مــن املــادة (‪ )41‬مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة‪  ،‬واملــادة الثالثــون مــن الالئحــة‬\n                                                                        ‫التنفيذيــة ‪.‬‬\n‫‪ .2‬عقوبــة املنــع مــن دخــول اململكــة وفقــا للفقــرة الثانيــة مــن املــادة (‪)56‬‬\n                                                                ‫مــن النظــام نفســه‪.‬‬\n                   ‫‪ .3‬عقوبة تعزيرية لقاء حيازته ما يعتقد بانها مخدرات ‪.‬‬\n‫هكــذا ادعــى وقــد حضــر املدعــى عليــه املذكــور بعاليــه وبســؤاله عــن‬\n‫ا ‪ :‬صحيــح مــا ذكــره املدعــي العــام‬      ‫دعــوى املدعــي العــام أجــاب قائ ـ ً‬\n‫مــن اتهامــي بحيــازة ثالثــة ســجائر يعتقــد أنهمــا ممزوجــة باحلشــيش مــن‬\n‫ضمن ســتة ســجائر يف علبة ســجائر وكان قصدي من ذلك االســتعمال‬\n‫وقــد حتصلــت علــى هــذا الســجائر مــن شــخص يف محافظــة القريــات‬\n‫واشــتريتها منــه علــى أنهــا ممزوجــة باحلشــيش ولســت متأكــد ًا بأنهــا‬\n‫ممزوجــة بذلــك وقــد ســبق وأن تعاطيــت احلشــيش و أنــا تائــب ونــادم هــذه‬\n‫إجابتــي وباالطــاع علــى أوراق املعاملــة وجــدت باللفــة رقــم (‪ )35‬التقريــر‬\n‫الكيميائــي الشــرعي رقــم (‪2450‬م ‪ /‬م س ت ) وتاريــخ ‪1434/9/10‬ه ـ‬\n‫واملتضمــن ســلبية مســتخلص العينــة ألي مــادة مشــتبهة أ‪ .‬ه ـ فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى و اإلجابــة وملــا تضمنــه التقريــر املخبــري  املنــوه‬\n‫عــن أعــاه ومبــا أن ظهــر لــي مــا يلــي ‪ :‬أوالً‪ :‬أن املدعــى عليــه صــادق‬\n‫علــى دعــوى املدعــي العــام بتعاطــي احلشــيش املخــدر ‪ .‬ثانيـاً‪ :‬أن املدعــى‬\n‫عليــه أقــر بحيــازة ســتة ســجائر و يعتقــد أن ثالثــة منهــا ممزوجــة مبــادة‬\n‫احلشــيش املخــدر وقــد أثبــت التقريــر املخبــري ســلبية مســتخلص العينــة‬\n‫ألي مــادة مشــتبهة وقــد تقــرر عنــدا الفقهــاء بــأن ال عبــرة بالظــن البــن‬\n‫خطــوة و أن الظــن إذا كان كاذبـ ًا فــا أثــر له ينظر‪( :‬األشــباه والنظائر‬\n\n\n                                                                                        ‫‪214‬‬\n\f      ‫للســبكي ‪243/1‬؛ واملنثــور للزكشــي ‪ ،353/2‬واألشــباه والنظائــر‬\n      ‫للســيوطي ‪ ،157/1‬غمــز عيــون البصائــر يف شــرح األشــباه والنظائــر‬\n      ‫‪ )460/1‬فتأسيسـ ًا علــى مــا ســبق ومبــا أن العبــرة مبــا يف نفــس األمــر ال‬\n             ‫مبــا يف ظــن املكلــف فقــد حكمــت علــى املدعــى عليــه مبــا يلــي‪:‬‬\n      ‫أوالً‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بتعاطــي احلشــيش املخــدر ويحــد‬\n                                  ‫لذلــك بجلــدة ثمانــن جلــدة حــد املســكر علنــا‬\n      ‫ثانيـ ًا ‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بحيــازة ســتة ســجائر عاديــة بقصــد‬\n      ‫االســتعمال و ثالثــة منهــا يعتقــد املدعــي عليــه أن ممزوجــة باحلشــيش‬\n      ‫ويعــزر املدعــى عليــه حليــازة هــذه الســجائر ولســوء قصــده بأخــذ التعهــد‬\n                                              ‫ال‬\n                                              ‫عليــه بعــدم العــودة ملثــل ذلــك مســتقب ً‬\n      ‫ثالث ـاً‪ :‬إبعــاد املدعــى عليــه خــارج البــاد وفق ـ ًا للمــادة (‪ )56‬مــن نظــام‬\n                                                                ‫مكافحــة املخــدرات‪.‬‬\n      ‫رابعـاً‪  :‬صــرف النظــر عــن طلــب املدعــي معاقبــة املدعــى عليــه وفــق املــادة‬\n      ‫(‪ )41‬مــن نظــام مكافحــة املخــدرات بإعــان احلكــم علــى الطرفــن‬\n      ‫قــررا جميعـ ًا االعتــراض عليــه بــدون الئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n       ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‪1434/10/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n      ‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف باجلــوف علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بعرعربرقــم‪342208967‬و‬\n      ‫تاريخ‪1434/10/21‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪....‬‬\n      ‫املســجل برقم‪34329233‬يف‪1434/10/13‬ه ـ اخلــاص بدعــوى املدعــي‬\n      ‫العــام ضــد‪ ....‬كويتــي اجلنســية يف قضيــة مخــدرات وقــد تضمــن القــرار‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة‬\n\n\n‫‪215‬‬\n\f‫ضبطــه وأوراق املعاملــة‪ .‬قررنــا املصادقــة علــى احلكــم‪ .‬واهلل املوفــق‬\n               ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                               ‫‪216‬‬\n\f217\n\f218\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":211,"source_page_end":218,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c7feb2181657ea4a73278eece157356f8be5e847c3a2704b4bff48bf50fdce24","normalized_text_hash":"a00afad24107ffc77bc916e414483abff000520e2e1970b04403e35d50b0a51a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p211-34329233"},{"id":"d238d60f-49b0-5a8b-8eba-276ec37d5f22","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى عامة باإلجتار باألشخاص -انكار الدعوى -عدم البينة -رد الدعوى لعدم ثبوتها.","document_number":"3457196","case_number":"3413714","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بالرياض بعد إحالتها إلي","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/07","year":"1434","subject":"دعوى عامة باإلجتار باألشخاص -انكار الدعوى -عدم البينة -رد الدعوى لعدم ثبوتها.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3457196:‬تاريخه‪1434/03/07 :‬هـ‬\n                          ‫رقم الدعوى‪3413714:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪  34188040‬تاريخه‪1434/04/15:‬هـ‬\n\n\n      ‫دعــوى عامــة باإلجتــار باألشــخاص ‪ -‬انــكار الدعــوى ‪ -‬عــدم البينــة ‪ -‬رد‬\n                                                         ‫الدعــوى لعــدم ثبوتهــا‪.‬‬\n\n\n\n\n      ‫‪ -‬مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة يف‬\n                                                                ‫تســبيب حكمــة‪.‬‬\n\n\n\n\n      ‫اتهــام املدعــى عليــه باإلجتــار باألشــخاص واســتغالل ضعــف مــن يقــوم‬\n      ‫باإلجتــار بهــن ‪ ،‬وذلــك بعدمــا مت القبــض علــى املذكــور مــن قبــل اجلهــات‬\n      ‫املختصــة إثــر تلقــي بــاغ  مفــاده قيامــه بعــرض العامــات املنزليــة للعمــل‬\n      ‫داخــل احلــي‪ ،‬ومت ضبــط املذكــور وبرفقته عاملتان منزليتان ‪ -‬بالبحث‬\n      ‫عــن ســوابقه لــم يعثــر لــه علــى ســوابق ‪ -‬طلــب املدعــي العــام معاقبــة‬\n      ‫املدعــى عليــه وفق ـ ًا للمــادة (الثالثــة) مــن نظــام االجتــار باألشــخاص‪-‬‬\n      ‫بعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أنكرهــا ودفــع بأنــه‬\n      ‫مجــرد ســائق وانــه حضــر إليصــال اخلادمــات مقابــل مبلــغ مالــي‪ -‬نظــرا‬\n      ‫إلنــكار املدعــى عليــه دعــوى املدعــي العــام ولعــدم وجــود بينة ســوى بالغ‬\n      ‫املبلــغ وهــي مجــرد دعــوى ال يثبــت بهــا شــيء لــذا لــم تثبــت إدانــة املدعــى‬\n      ‫عليــه‪ ،‬ومت احلكــم بــرد دعــوى املدعــي العــام‪ -‬بعــرض احلكــم علــى‬\n\n‫‪219‬‬\n\f‫املدعــى عليــه قــرر القناعــة وقــرر املدعــي العــام عدمهــا مكتفيــا بالئحــة‬\n‫االدعــاء‪ ،‬وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليهــا‪.‬‬\n\n\n\n\n  ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة اجلزائيــة‬\n  ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n  ‫اجلزائيــة بالريــاض برقــم ‪ 3413714‬وتاريــخ ‪ 1434/01/10‬هــ  املقيــدة‬\n‫باحملكمــة برقــم ‪ 3464451‬وتاريــخ ‪ 1434/01/10‬هــ   ففــي يــوم  ‬\n‫االثنــن املوافــق‪ 1434/03/02‬ه ـ افتتحــت اجللســة الســاعة ‪  11 : 00‬‬\n  ‫وفيهــا حضــر املدعــي العــام ‪........‬وقــدم دعــواه بورقــة محــررة مرفقــة‬\n  ‫مــع املعاملــة قائــا فيهــا ‪ :‬بصفتــي عضــو هيئــة التحقيــق واالدعــاء العــام‬\n  ‫مبدينــة الريــاض ادعــي علــى ‪ 43 ........ /‬عامــا ‪ ،‬باكســتاني اجلنســية‬\n  ‫مبوجــب رخصــة اإلقامــة رقــم (‪ )........‬محصــن ‪ -‬متعلــم ‪ ،‬موقــوف‬\n  ‫بتاريــخ ‪1433/12/19‬ه ـ مبوجــب أمــر التوقيــف رقــم ‪........‬وتاريــخ‬\n  ‫‪1433/12/19‬ه ـ وأحيــل لشــعبة ســجن امللــز مبوجــب أمــر حالــة ومتديــد‬\n  ‫توقيــف رقم‪........‬وتاريــخ ‪1433/12/28‬ه ـ اســتناد ًا للمــادة (‪ )113‬مــن‬\n  ‫نظــام اإلجــراءات اجلزائيــة ‪.‬حيــث إنــه بتاريــخ ‪1433/12/18‬ه ـ قبــض‬\n  ‫علــى املذكــور مــن قبــل إحــدى فــرق الدوريــات األمنيــة بعــد تلقــي بــاغ‬\n  ‫مــن املواطــن‪ -........ /‬مفــاده قيــام املذكــور بعــرض العامــات املنزليــة‬\n  ‫للعمــل داخــل احلــي ويســتقل ســيارة نــوع ‪ ......‬رقــم اللوحــة (‪ )........‬وبانتقال‬\n  ‫الفرقــة مت ضبــط املذكــور وبرفقــه عاملتــان منزليتان هما املــرأة‪........ /‬‬\n  ‫واملــرأة‪ ،......../‬اندونيســيتي اجلنســية ( صــدر بحقهمــا أمــر حفــظ أوراق‬\n  ‫) وبســماع أقــوال األول واســتجوابه ‪ /‬اقــر بــإركاب العاملتــن املنزليتــن‬\n                                                                                           ‫‪220‬‬\n\f      ‫والقبــض عليهــم جميع ـ ًا معــه يف الســيارة ‪ -‬كمــا اقــر بالذهــاب إلــى‬\n      ‫منــزل املدعــي والوقــوف أمامــه ‪.‬وقــد أســفرت إجــراءات التحقيــق عــن‬\n      ‫اتهامــه باإلجتــار باألشــخاص واســتغالل ضعــف مــن يقــوم باإلجتــار بهــن‬\n      ‫املعاقــب عليــه بنظــام مكافحــة االجتــار باألشــخاص الصــادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )40/‬وتاريــخ ‪1433/7/21‬هـ‪.‬وذلــك لألدلــة والقرائــن‬\n                                                                                    ‫التاليــة ‪:‬‬\n      ‫مــا جــاء بأقــوال األول املدونــة ص (‪ )12-11‬مــن ملــف ســماع األقــوال‬\n      ‫املرفــق لفــه (‪ )1‬وعلــى الصفحــة (‪ )1‬مــن دفتــر االســتجواب املرفــق لفــه‬\n      ‫رقــم (‪ 0.2)14‬محضــر القبــض املرفــق لفــه رقــم (‪.)4‬وببحــث ســوابقه‬\n      ‫لــم يعثــر لــه علــى ســوابق مســجلة حتــى تاريخــه‪ 0‬وحيــث إن مــا أقــدم‬\n      ‫عليــه املذكــور فعــل معاقــب عليــه نظام ـ ًا أطلــب إثبــات مــا أســند‬\n      ‫إليــه ومعاقبتــه وفق ـ ًا للمــادة (الثالثــة) مــن النظــام املشــار إليــه ‪ .‬وبــاهلل‬\n      ‫التوفيــق وبســؤال املدعــى عليــه عــن دعــوى املدعــي العــام أجــاب قائــا‬\n      ‫مــا ذكــره املدعــي العــام كلــه غيــر صحيــح وأنــا مجــرد ســائق وقــد‬\n      ‫حضــرت إليصــال اخلادمــات مــن بيــت املبلــغ إلــى بيــت ‪ .......‬هكــذا أجــاب‬\n      ‫وبســؤال املدعــي العــام البينــة علــى دعــواه قــال ال بينــة لــدي ســوى مــا يف‬\n      ‫الئحــة االدعــاء وباالطــاع عليهــا وجــدت أقوالــه يف دفتــر التحقيــق علــى‬\n      ‫اللفــة ‪ 14‬ص ‪ 1‬ونــص احلاجــة منهــا س‪ /‬انــت متهــم بتشــغيل اخلادمــات‬\n      ‫بطريقــة غيــر نظاميــه ؟ ج‪ /‬ال غيــر صحيــح س‪/‬أنــت متهــم بإيوائهــن ؟ ج‪/‬‬\n      ‫هــذا لــم يحصــل س‪ /‬مــا عالقتــك باخلادمــة ؟ ج‪ /‬ال يوجــد عالقــة أعمــل‬\n      ‫لــدى كفيلــي ‪........‬وطلــب منــي أن أذهــب  وأحضــر لــه خادمــة مــن منــزل‬\n      ‫املدعــي ‪........ /‬وبعــد أن قمــت بأخــذ اخلادمــة مــن منــزل املدعــي وأثنــاء‬\n      ‫وقــويف عنــد منــزل كفيلــي حضــرت الدوريــات وقبضــت علــي وأنــا ال‬\n\n\n‫‪221‬‬\n\f  ‫عالقــة لــي باخلادمــة أ‪.‬ه ـ كمــا جــرى االطــاع علــى محضــر القبــض  لفــة‬\n  ‫‪ 4‬ونــص احلاجــة منــه أنــه أثنــاء قيــام الفرقــة بعملهــا تلقــت بالغ ـ ًا عــن‬\n  ‫وجــود شــخص باكســتاني يعــرض خادمــات للعمــل فتــم القبــض علــى‬\n  ‫الشــخص املذكــور معــه اخلادمــات أ‪.‬ه ـ ملخص ـ ًا فجــرى ســؤال املدعــي‬\n  ‫العــام هــل لديــه مزيــد بينــة فقــال ليــس لــدي ســوى مــا قدمــت فبنــاء علــى‬\n  ‫مــا تقــدم مــن الدعــوى واإلجابــة ونظــرا إلنــكار املدعــى عليــه دعــوى‬\n  ‫املدعــي العــام ولعــدم وجــود بينــة ســوى بــاغ املبلــغ وهــي مجــرد دعــوى ال‬\n  ‫يثبــت بهــا شــيء لــذا فلــم يثبــت لــدي إدانــة املدعــى عليــه وحكمــت بــرد‬\n  ‫دعــوى املدعــي العــام وبعرضــه عليهمــا قــرر املدعــى عليــه القناعــة وقــرر‬\n  ‫املدعــي العــام عــدم القناعــة مكتفيــا بالئحــة االدعــاء وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف  ‬\n  ‫‪ 1434/03/02‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي‬\n  ‫باحملكمــة اجلزائيــة بالريــاض ففــي يــوم األحــد  املوافــق  ‪/ 05  /26‬‬\n  ‫‪ 1434‬ه ـ فتحــت اجللســة الســاعة احلاديــة عشــر صباحــا بعــد أن تلقيــت‬\n  ‫املعاملــة مــن محكمــة االســتئناف بالريــاض بعــد إحالتهــا إلــي مــن‬\n  ‫فضيلــة الرئيــس برقــم ‪ 34/10960530‬يف ‪1434/ 05 /05‬ه ـ وبرفقهــا‬\n  ‫قــرار أصحــاب الفضيلــة قضــاة الدائــرة الثالثــة  لتمييــز القضايــا اجلزائية‬\n  ‫مبحكمــة االســتئناف بالريــاض برقــم ‪ 34188040‬يف ‪/04 /15‬‬\n  ‫‪ 1434‬ه ـ واملتضمــن املصادقــة علــى مــا حكمــت بــه باألكثريــة وعــدم‬\n  ‫االعتــراض عليــه وقــد جــرى إثبــات ذلــك كلــه حســب التعليمــات وأمــرت‬\n  ‫ببعــث املعاملــة إلــى جهــات التنفيــذ الكتســابها القطعيــة وختمت اجللســة‬\n  ‫الســاعة احلاديــة عشــر والنصــف وحــرر يف ‪1434/05/26‬هــ  و صلى اهلل‬\n                                                                  ‫علــى نبينــا محمــد‪.‬‬\n\n\n                                                                                          ‫‪222‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":219,"source_page_end":222,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9cd053687f70f4866255ae203f920710253c5fde8e9d357af2e0f8cdf43c4017","normalized_text_hash":"67c6850b907bf51efe12f03b3fe7b7d01491ed408b4acca6fa9f27e0d55206da","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p219-3457196"},{"id":"05b01727-fb6d-56cf-9722-4f3ba97a5832","document_type":"judgment","category":"judicial","subcategory":"general","title":"اجتار بالبشر بامتهان القوادة -امتهان الدعارة -تعزير بالسجن واجللد والغرامة واإلبعاد -تغليظ التعزير يف جرائم القوادة .","document_number":"3461001","case_number":"33677560","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف وبرفقها القرار","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/14","year":"1434","subject":"اجتار بالبشر بامتهان القوادة -امتهان الدعارة -تعزير بالسجن واجللد والغرامة واإلبعاد -تغليظ التعزير يف جرائم القوادة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3461001:‬تاريخه‪1434/03/14 :‬هـ‬\n                         ‫رقم الدعوى‪33677560:‬‬\n                   ‫رقم قرار التصديق من محكمة‬\n       ‫االستئناف‪ 34188040:‬تاريخه‪1434/05/29:‬هـ‬\n\n\n      ‫اجتــار بالبشــر بامتهــان القــوادة ‪ -‬امتهــان الدعــارة ‪ -‬تعزيــر بالســجن‬\n         ‫واجللــد والغرامــة واإلبعــاد ‪ -‬تغليــظ التعزيــر يف جرائــم القــوادة ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قــول اهلل تعالــى ( إن الذيــن يحبــون أن تشــيع الفاحشــة يف الذيــن‬\n                                   ‫آمنــوا لهــم عــذاب أليــم يف الدنيــا واآلخــرة )‪.‬‬\n      ‫‪ -2‬مــا قــرره أهــل العلــم مــن تغليــظ التعزيــر يف جرائــم القــوادة ينظــر ‪:‬‬\n                             ‫مجمــوع فتــاوى شــيخ اإلســام ابــن تيميــة (‪.)181/34‬‬\n      ‫‪ -3‬مــا جــاء يف املادتــن الثالثــة والرابعــة‪ ،‬مــن نظــام مكافحــة االجتــار‬\n                                                                            ‫بالبشــر ‪.‬‬\n\n\n\n\n      ‫انتهــى التحقيــق إلــى اتهــام املدعــى عليهـ ّـن (ثــاث نســاء مقيمــات) األولــى‬\n      ‫باالجتــار باألشــخاص وذلــك بامتهــان القــوادة علــى الثانيــة والثالثــة‪،‬‬\n      ‫واتهــام الثانيــة والثالثــة بامتهــان الدعــارة‪ ،‬وذلــك بعدمــا قبــض عليهـ ّـن‬\n      ‫مــن قبــل اجلهــات املختصــة بعــد ورود معلومــات عــن قيــام األولــى بامتهــان‬\n      ‫القــوادة علــى النســاء مقابــل املــال ‪ -‬بالبحــث عــن ســوابقهن اتضــح‬\n      ‫خلــو ســجالتهن مــن الســوابق‪ -‬طلــب املدعــي العــام احلكــم عليهــن‬\n      ‫بعقوبــة تعزيريــة‪ ،‬ومعاقبــة األولــى وفــق املــادة الثالثــة مــن نظــام االجتــار‬\n\n‫‪223‬‬\n\f‫باألشــخاص‪ ،‬وتشــديد العقوبــة عليهــا وفــق املــادة الرابعــة مــن ذات‬\n‫النظــام‪ -‬بعــرض دعــوى املدعــي العــام علــى املدعــى عليهــن أنكرنهــا‬\n‫جملة وتفصيالً‪ -‬مت ســماع شــهادة الشــهود‪ ،‬وبعرض الشــهود وشــهادتهم‬\n‫علــى املدعــى عليهــن أنكــرن الشــهادة‪ ،‬ولــم يطعـ ّـن يف الشــهود‪ -‬نظر ًا ملا‬\n‫جــاء يف شــهادة الشــهود مــن ســماعهم إلقــرار املدعــى عليهــا األولــى أنهــا‬\n‫تقــود مقابــل مبالــغ ماليــة ورؤيتهــم لذلــك وســماعهم ملفاوضــة املصــدر‬\n‫للمدعــى عليهــا ‪ ..‬يف جلــب نســاء لــه إلحيــاء ســهرة آثمــة وســماعهم إقــرار‬\n‫املدعــى عليهمــا الثانيــة والثالثــة أنهــن خرجــن إلحيــاء ســهرة آثمــة وملــا‬\n‫قــرره أهــل العلــم مــن تغليــظ التعزيــر يف جرائــم القــوادة‪ ،‬وألن ذلــك‬\n‫ضــرب مــن حــب نشــر الفاحشــة بــن املؤمنــن‪ ،‬ولظهــور امتهــان املدعــى‬\n‫عليهمــا الثانيــة والثالثــة للدعــارة بداللــة حــال الواقعــة لــذا ثبتــت إدانــة‬\n‫املدعــى عليهــا األولــى باإلجتــار بالبشــر بامتهــان القــوادة علــى املدعــى‬\n‫عليهــن الثانيــة والثالثــة ونشــر الفاحشــة وإدانــة املدعــى عليهــن الثانيــة‬\n‫والثالثــة بامتهــان الدعــارة ومت احلكــم مبــا يلــي ‪ /1 :‬ســجن املدعى عليها‬\n‫األولــى أربــع ســنوات وجلدهــا أربعمائــة جلــدة مفرقــة علــى ثمــان دفعــات‬\n‫وتغرميهــا أربعــة آالف ريــال ‪ /2‬ســجن كل مــن املدعــى عليهــن الثانيــة‬\n‫والثالثــة ســنتني وجلــد كل واحــدة منهــن مائتــن وخمســن جلــدة مفرقــة‬\n‫علــى خمــس دفعــات مــع التوصيــة بإبعادهــن عــن البــاد بعــد تصفيــة مــا‬\n‫لهــن وعليهــن مــن حقــوق‪ -‬بعــرض احلكــم علــى املدعــى عليهــن قــررن‬\n‫القناعــة باحلكــم وقــرر املدعــي العــام االعتــراض مكتفيــا بالئحــة‬\n‫الدعــوى‪ ،‬وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n                                                                                        ‫‪224‬‬\n\f        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪   ........‬القاضــي يف احملكمــة اجلزائيــة‬\n        ‫بالريــاض   وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n        ‫اجلزائيــة بالريــاض برقــم ‪ 33677560‬وتاريــخ ‪ 1433/11/27‬هــ  املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332122087‬وتاريــخ ‪ 1433/11/27‬هــ  ففــي يــوم  ‬\n        ‫األحــد املوافــق‪ 1434/01/11‬ه ـ افتتحــت اجللســة الســاعة‪ 08 : 15‬وفيها‬\n        ‫قدم املدعي العام ‪........‬ضد ‪32  ........-1‬سنة  صومالية اجلنسية مبوجب‬\n        ‫إثبــات الهويــة املؤقــت محصنــة  مســلمة  موقوفــة بتاريــخ ‪1433/11/4‬ه ـ‬\n        ‫مبوجــب أمــر التوقيــف رقــم   ‪........‬وتاريخ‪1433/11/3‬ه ـ ومــدد لهــا‬\n      ‫مبوجــب أمــر إحالــة ومتديــد توقيــف رقــم ‪ ........‬وتاريــخ ‪1433/11/13‬هــ  ‬\n                                   ‫اســتناد ًا للمــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيـة    ‬\n        ‫‪ 35........ -2‬ســنة صوماليــة اجلنســية مبوجــب إثبــات الهويــة املؤقــت‬\n        ‫محصنــة  مســلمة  موقوفــة بتاريــخ ‪1433/11/3‬ه ـ مبوجــب أمر التوقيف‬\n        ‫رقم‪........‬وتاريــخ   ‪1433/11/3‬ه ـ ومــدد لهــا مبوجــب أمــر إحالــة ومتديــد‬\n        ‫توقيــف رقــم ‪........‬وتاريــخ ‪1433/11/10‬هــ  اســتناد ًا للمــادة (‪ )121‬مــن‬\n                                                                    ‫نظــام اإلجــراءات اجلزائيــة‬\n        ‫‪ 27 ،........ -3‬ســنة ‪ ،‬صوماليــة اجلنســية مبوجــب إثبــات الهويــة املؤقــت‬\n        ‫محصنــة ‪ ،‬مســلمة ‪ ،‬موقوفــة بتاريــخ ‪1433/11/3‬ه ـ مبوجــب أمــر‬\n        ‫التوقيــف رقــم  ‪ ........‬وتاريــخ   ‪1433/11/3‬ه ـ ومــدد لهــا مبوجــب أمــر‬\n        ‫إحالــة ومتديــد توقيــف رقــم ‪........‬وتاريــخ ‪1433/11/13‬هــ   اســتناد ًا‬\n                         ‫للمــادة (‪ )121‬مــن نظــام اإلجــراءات اجلزائيــة               ‪    .‬‬\n        ‫حيــث إنــه بتاريــخ ‪1433/11/3‬ه ـ قبــض علــى املذكوريــن مــن قبــل هيئة‬\n\n\n‫‪225‬‬\n\f‫األمــر باملعــروف والنهــي عــن املنكــر ‪ ،‬مركــز هيئــة ‪........‬بعــد ورود‬\n‫معلومــات عــن قيــام األولــى بامتهــان القــوادة علــى النســاء مقابــل املــال‬\n‫وحضــر شــخص إلــى املركــز وأفــاد أن األولــى عرضــت عليــه الثانيــة‬\n‫والثالثــة فتــم االتصــال عليهــا واتفقــت مــع املصــدر علــى مبلــغ (‪)1000‬‬\n‫ريــال لــكل واحــدة إلحيــاء ســهرة وســلم املبلــغ املرقــم واالنتقــال للموقــع‬\n‫املتفــق عليــه وحضــرت األولــى ومعهــا الثانيــة والثالثــة علــى ســيارة أجــرة‬\n‫وقابلــت املصــدر وأخــذت املــال ثــم عــادت إلــى ســيارة األجــرة وأنزلــت‬\n     ‫الثانيــة والثالثــة وركبــوا جميع ـ ًا مــع املصــدر فتــم القبــض عليهــم ‪  .‬‬\n‫وقــد أســفرت إجــراءات التحقيــق عــن اتهــام األولــى باإلجتار باألشــخاص‬\n‫وذلــك بامتهــان القــوادة علــى الثانيــة والثالثــة املجرم مبوجب املــادة الثالثة‬\n‫مــن نظــام اإلجتــار باألشــخاص الصــادر باملرســوم امللكــي رقــم (م‪) 40/‬‬\n‫وتاريــخ ‪1430/7/21‬ه ـ واتهــام الثانيــة والثالثــة بامتهــان الدعــارة وذلــك‬\n                                                        ‫لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪ -1‬مــا جــاء يف محضــر االتصــال املنــوه عنــه مبحضــر القبــض املرفــق لفــه‬\n                                                                          ‫( ‪. )16-15‬‬\n             ‫‪ -2‬ما جاء يف محضر املبلغ املرقم مبحضر القبض املرفق لفه‬\n                                                                           ‫(‪. )16-15‬‬\n                         ‫‪ -3‬ما جاء يف محضر القبض املرفق لفه (‪. )16-15‬‬\n‫وببحــث ســوابقهم اتضــح خلــو ســجالتهم مــن الســوابق حتــى تاريخــه‬\n‫وحيــث إن مــا أقــدم عليــه املذكــورون فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫أطلــب إثبــات مــا أســند إليهــم واحلكــم عليهــم بعقوبــة تعزيريــة لقــاء مــا‬\n‫أســند إليهــم ومعاقبــة األولــى وفــق املــادة الثالثــة وتشــديد العقوبــة عليهــا‬\n‫وفــق املــادة الرابعــة مــن نظــام االجتــار باألشــخاص املشــار إليــه وبعــرض‬\n\n\n                                                                                          ‫‪226‬‬\n\f        ‫ذلــك علــى املدعــى عليهــن أنكــرن الدعــوى وقالــت املدعــى عليهــا ‪........‬‬\n        ‫لقــد حضــرت املدعــى عليهــا ‪........‬و‪ ........‬إلــى بيتــي للغــداء ثــم أردن‬\n        ‫أن يذهــن لســوق ‪........‬فذهبــت  معهــن للســوق املذكــور وأنزلتهــن ثــم‬\n        ‫رجعــت لبيتــي مــع ســيارة األجــرة  فتــم القبــض علــي يف ســيارة األجرة ولم‬\n      ‫أقــم بالقــوادة أبــدا هكــذا أجابــت وأجابــت املدعــى عليهمــا  األخريتــان  ‬\n        ‫مبثــل جــواب املدعــى عليهــا ‪........‬ولطلــب البينــة جــرى رفــع اجللســة ألقرب‬\n        ‫موعد وعليه جرى التوقيع وأغلقت اجللســة الســاعة ‪ 08 : 45‬وصلى اهلل‬\n        ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/01/11‬ه ـ‬\n        ‫ففــي يــوم األربعــاء ‪1434/02/27‬ه ـ لــدي أنــا ‪........‬القاضــي باحملكمــة‬\n        ‫اجلزائيــة بالريــاض افتتحــت اجللســة الســاعة و فيهــا أحضــر املدعــى العــام‬\n        ‫شــاهد ًا هــو ‪........‬يحمــل ســجل مدنــي رقــم (‪ )........‬و بســؤاله عمــا لديــه‬\n        ‫ا عمــري (‪ )45‬ســنة و أســكن يف الريــاض و أعمــل عضــوا يف‬               ‫أجــاب قائـ ً‬\n        ‫هيئــة األمــر باملعــروف و النهــي عــن املنكــر مركــز هيئــة ‪........‬و أحمــل‬\n        ‫املؤهــل اجلامعــي وال تربطنــي باملدعــى عليهمــا عالقــة و أشــهد أنــه و‬\n        ‫ردتنــا املعلومــات عــن املدعــى عليهــا األولــى ‪........‬أنهــا تقــوم بالقــوادة علــى‬\n        ‫النســاء مقابــل مبالــغ ماليــة و يف يــوم األربعــاء ‪1433/11/3‬ه ـ حضــر‬\n        ‫أحــد األشــخاص و ذكــر أن املدعــى عليهــا األولــى ‪........‬قــد عرضــت‬\n        ‫عليــه اثنتــن مــن النســاء لفعــل الفاحشــة بهــن مقابــل ألــف ريــال لــكل‬\n        ‫واحــدة يف الليلــة و قــام باالتصــال علــى املدعــى عليــه األولــى ‪........‬و‬\n        ‫مبجــرد ردهــا علــى الهاتــف رحبــت بــه و نحــن نســمع وعرضــت عليــه‬\n        ‫إحيــاء الســهرة مقابــل ألــف ريــال لــكل واحــدة مــن البنــات و ألــف ريــال‬\n        ‫لهــا مقابــل إحضــار النســاء و ســلم املبلــغ املرقــم للمصــدر و قــدره ألــف‬\n        ‫ريــال و طلبــت املدعــى عليــه األولــى ‪........‬مــن املصــدر مقابلتهــا أمــام أحــد‬\n\n\n‫‪227‬‬\n\f‫احملــات التجاريــة و باالنتقــال للموقــع شــاهدنا املدعــى عليهــا األولــى‬\n‫‪........‬و معهــا املدعــى عليهــا الثانيــة ‪........‬و الثالثــة ‪........‬يف ســيارة أجــرة‬\n‫و فــور مشــاهدة املدعــى عليهــا ‪........‬للمصــدر قامــت بالنــزول و أخــذت‬\n‫املبلــغ مــن املصــدر ثــم رجعــت لســيارة األجــرة و أمــرت النســاء بالنــزول و‬\n‫ركــب اجلميــع يف ســيارة املصــدر فتــم ضبطهــم و تبــن أن املدعــى عليهــا‬\n‫األولــى ‪........‬هــي املــرأة املذكــورة يف بــاغ املبلــغ كمــا أفــادت املدعــى‬\n‫عليــه األولــى ‪........‬أنهــا تقــوم بالقــوادة مقابل مبالغ مالية و أفادت املدعى‬\n‫عليــه الثانيــة ‪........‬و املدعــى عليــه الثالثــة ‪........‬أنهن خرجن إلحياء ســهرة‬\n‫آثمــة هــذا مــا لــدي و بــه أشــهد كمــا أحضــر املدعــى العــام شــاهد ًا هــو‬\n‫ا‬\n‫‪........‬يحمــل ســجل مدنــي رقــم (‪ )........‬و بســؤاله عمــا لديــه أجــاب قائـ ً‬\n‫عمــري (‪ )45‬ســنة و أســكن يف الريــاض و أعمــل عضــوا يف هيئــة األمــر‬\n‫باملعــروف و النهــي عــن املنكــر مركــز هيئــة ‪........‬و أحمــل املؤهــل‬\n‫اجلامعــي و ال تربطنــي باملدعــى عليهمــا عالقــة و أشــهد شــهادة مطابقــة‬\n‫لشــهادة األول كمــا أحضــر املدعــى العــام شــاهد ًا هــو ‪........‬يحمل ســجل‬\n‫ا عمــري (‪ )28‬ســنة‬    ‫مدنــي رقــم (‪ )........‬و بســؤاله عمــا لديــه أجــاب قائـ ً‬\n‫و أســكن يف الريــاض و أعمــل عضــوا يف هيئــة األمــر باملعــروف و النهــي‬\n‫عــن املنكــر مركــز هيئــة ‪........‬و أحمــل املؤهــل الثانــوي و ال تربطنــي‬\n‫باملدعــى عليهمــا عالقــة و أشــهد شــهادة مطابقــة لشــهادة األول و لطلــب‬\n‫املدعــى عليهمــا جــرى رفــع إلــى أقــرب وقــت وعليــه جــرى التوقيــع و صلــى‬\n‫اهلل وســلم علــى نبينــا محمــد و علــى آلــه و صحبــه  احلمــد هلل وحــده‬\n‫وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة اجلزائيــة بالريــاض ففــي يــوم‬\n‫األربعــاء املوافــق ‪1434/03/11‬ه ـ افتتحــت اجللســة الســاعة العاشــرة‬\n‫وفيهــا حضــر املدعــى عليهــن ‪........‬و‪ ........‬و‪ ........‬املشــار إلــى هوياتهــن يف‬\n\n\n                                                                                            ‫‪228‬‬\n\f      ‫اجللســة الســابقة وبعــرض الشــهود وشــهادتهن علــى املدعــى عليهــن قلــن‬\n      ‫إن الشــهادة غيــر صحيحــة ونحــن ال نعــرف الشــهود فبنــاء علــى مــا ســلف‬\n      ‫مــن الدعــوى واإلجابــة وملــا جــاء يف شــهادة أعضــاء الهيئــة مــن ســماعهم‬\n      ‫إلقــرار املدعــى عليهــا مــرمي أنهــا تقــود علــى النســاء مقابــل مبالــغ ماليــة‬\n      ‫ورؤيتهــم لذلــك وســماعهم ملفاوضــة املصــدر للمدعــى عليهــا ‪........‬يف‬\n      ‫جلــب نســاء لــه إلحيــاء ســهرة آثمــة وســماعهم إقــرار املدعــى عليهــا‬\n      ‫‪........‬و‪........‬أنهــن خرجــن إلحيــاء ســهرة آثمــة وملــا قــرره أهــل العلــم مــن‬\n      ‫تغليــظ التعزيــر يف جرائــم القــوادة ينظــر ‪ :‬مجمــوع فتــاوى شــيخ اإلســام‬\n      ‫ابــن تيميــة (‪ )181/34‬وألن ذلــك ضــرب مــن حــب نشــر الفاحشــة بــن‬\n      ‫املؤمنــن ولقــول اهلل تعالــى ( إن الذيــن يحبــون أن تشــيع الفاحشــة يف‬\n      ‫الذيــن آمنــوا لهــم عــذاب أليــم يف الدنيــا واآلخــرة ) ولظهــور امتهــان‬\n      ‫املدعــى عليهمــا ‪........‬و‪........‬للدعــارة بداللــة حــال الواقعــة وملــا جــاء يف‬\n      ‫املــادة (‪ )3‬و (‪ )4‬مــن نظــام مكافحــة االجتــار بالبشــر فقــد ثبــت لــدي‬\n      ‫إدانــة املدعــى عليهــا ‪........‬باإلجتــار بالبشــر بامتهــان القــوادة علــى املدعى‬\n      ‫عليهمــا ‪........‬و‪ ........‬ونشــر الفاحشــة وإدانــة املدعــى عليهــا ‪........‬و‪........‬‬\n      ‫بامتهــان الدعــارة وحكمــت مبــا يلــي ‪ /1 :‬ســجن املدعــى عليهــا ‪........‬‬\n      ‫أربــع ســنوات تبــدأ مــن تاريــخ اإليقــاف وجلدهــا أربعمائــة جلــدة مفرقــة‬\n      ‫علــى ثمــان دفعــات كل دفعــة خمســون جلــدة وتغرميهــا أربعــة آالف ريــال‬\n      ‫‪ /2‬ســجن كل مــن املدعــى عليهمــا ‪........‬و‪........‬ســنتني وجلدهــا مائتــن‬\n      ‫وخمســن جلــدة مفرقــة علــى خمــس دفعــات كل دفعــة خمســون جلــدة‬\n      ‫والســجن احملكــوم بــه يبــدأ مــن تاريــخ اإليقــاف وأوصــي بإبعادهــن‬\n      ‫عــن البــاد بعــد تصفيــة مــا لهــن وعليهــن مــن حقــوق وبعرضــه عليهــم‬\n      ‫قــرر املدعــى عليهــن القناعــة باحلكــم وقــرر املدعــي العــام االعتــراض‬\n\n\n‫‪229‬‬\n\f‫مكتفيــا بالئحــة الدعــوى وكان النطــق باحلكــم يف ‪1434/03/11‬ه ـ‬\n‫وأغلقنــا اجللســة الســاعة وعليــه جــرى التوقيــع وصلــى اهلل علــى نبينــا‬\n‫محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/03/11‬ه ـ ‪ .‬احلمــد هلل وحــده‬\n‫وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة اجلزائيــة بالريــاض ويف يــوم‬\n‫األربعــاء املوافــق ‪1434/06/14‬ه ـ افتتحــت اجللســة وقــد عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪ 34227584‬وتاريــخ‬\n‫‪1434/05/29‬ه ـ واملتضمــن املصادقــة علــى احلكــم وصلــى اهلل علــى‬\n            ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/06/14‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                   ‫‪230‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":223,"source_page_end":230,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ac4914636e09897f8a99d7ab0eed89d57f536abc602b15601d3b27f02f56869b","normalized_text_hash":"c3f7f5d8b3d5d905d7a5de2b5149d0fd60d9137e6391d7daf04cb3587b06f0dc","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p223-3461001"},{"id":"6151a13b-2f24-55e7-848f-98bd9d78d693","document_type":"judgment","category":"judicial","subcategory":"general","title":"اجتار بطفل عن طريق التسول -اإلقرار بالتسول -أثبت تقرير احلمض النووي أن الطفل ليس ابن ا للمدعى عليه -تعزير بالسجن مع التوصية باإلبعاد.","document_number":"34284025","case_number":"34198551","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية مبوجب اخلطاب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/30","year":"1434","subject":"اجتار بطفل عن طريق التسول -اإلقرار بالتسول -أثبت تقرير احلمض النووي أن الطفل ليس ابن ا للمدعى عليه -تعزير بالسجن مع التوصية باإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34284025:‬تاريخه‪1434/07/30 :‬هـ‬\n                          ‫رقم الدعوى‪34198551:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 34353183:‬تاريخه‪1434/11/06:‬هـ‬\n\n\n       ‫اجتــار بطفــل عــن طريــق التســول‪ -‬اإلقــرار بالتســول‪ -‬أثبــت تقريــر‬\n       ‫احلمــض النــووي أن الطفــل ليــس ابنـ ًا للمدعــى عليــه‪ -‬تعزير بالســجن‬\n                                                         ‫مــع التوصيــة باإلبعــاد‪.‬‬\n\n\n\n\n       ‫‪ -‬املــادة األولــى‪ ،‬والثانيــة‪ ،‬والثالثــة‪ ،‬والرابعــة‪ ،‬مــن نظــام االجتــار‬\n                                                                   ‫باأل شــخاص‪.‬‬\n\n\n\n\n       ‫انتهــى التحقيــق إلــى اتهــام املدعــى عليــه باإلجتــار بطفــل يبلــغ عمــره أربــع‬\n       ‫ســنوات مســتغال ضعفــه باســتخدامه يف التســول‪ ،‬وذلــك بعــد مــا متــت‬\n       ‫مالحظــة املدعــى عليــه ومعــه الطفــل املذكــور يقــوم بالتســول يف أحــد‬\n       ‫اجلوامــع‪ ،‬وتبــن أنــه ال يوجــد معــه إثبــات هويتــه وكذلــك احلــال بالنســبة‬\n       ‫للطفــل‪ -‬أثبــت تقريــر الفحــوص الوراثيــة (‪ )DNA‬أن املذكــور ليــس‬\n       ‫األب احلقيقــي للطفــل الــذي برفقتــه‪ -‬طلــب املدعــي العــام احلكــم علــى‬\n       ‫املدعــى عليــه بعقوبتــي الســجن والغرامــة وفــق مقتضــى املــادة الثالثــة مــن‬\n       ‫نظــام االجتــار باألشــخاص وتشــديد العقوبــة عليــه وفــق مقتضــى الفقــرة‬\n       ‫الثالثــة مــن املــادة الرابعــة مــن ذات النظــام‪ -‬بعــرض دعــوى املدعــي العــام‬\n       ‫علــى املدعــى عليــه صــادق علــى التســول بقصــد عــاج الطفــل الــذي‬\n\n‫‪231‬‬\n\f‫معــه‪ ،‬ودفــع بأنــه ابنــه وقــرر أنــه دخــل البــاد عــن طريــق التهريــب كمــا‬\n‫قــرر أنــه قــام بالتســول مــدة شــهر وعشــرة أيــام‪ -‬ثبتــت إدانــة املدعــى‬\n‫عليــه باإلجتــار باألشــخاص عــن طريــق التســول بالطفــل املذكــور ومت‬\n‫احلكــم عليــه بتعزيــره بالســجن ملــدة ســنة مــع التوصيــة بإبعــاده عــن‬\n‫البــاد‪ -‬بعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعــة‬\n‫وقــرر املدعــي العــام عدمهــا مت رفــع احلكــم حملكمــة االســتئناف ومتــت‬\n                                                               ‫املصادقــة عليــه‪.‬‬\n\n\n\n‫اجلزائيــة‬\n   ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة‬\n‫بالدمــام ويف يــوم الســبت املوافق‪1434/06/17‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 10 : 45‬وفيهــا قــدم املدعــي العــام ‪ .............‬دعــواه ضــد املدعــي‬\n‫ا فيهــا ‪ :‬إنــه باالطــاع علــى محضر تنفيذ مهمة املعد من‬          ‫عليــه ‪ ........‬قائـ ً‬\n‫قبــل  الدوريــات األمنيــة تبــن أنــه  يف قرابــة  الســاعة الســابعة مــن مســاء‬\n‫يــوم االثنــن املوافــق ‪1433/1/12‬ه ـ مت مالحظــة املدعــى عليــه ومعــه‬\n‫طفــل عمــره ‪ 4‬ســنوات يقــوم بالتســول يف جامــع ‪........‬بالدمــام وتبــن أنــه‬\n‫ال يوجــد معــه إثبــات هويتــه وكذلــك احلــال بالنســبة للطفــل ومت تســليمه‬\n‫لشــرطة شــمال الدمــام ( مت تســليم الطفــل للجهــة املختصــة لرعايتــه حلــن‬\n‫العثــور علــى ذويــه ) وأثبــت تقريــر الفحوص الوراثيــة (‪ )DNA‬رقم ‪........‬‬\n‫أن املذكــور ليــس األب احلقيقــي للطفــل الــذي برفقتــه وبســماع أقــوال‬\n‫املدعــى عليــه أفــاد أنــه قــدم للمملكــة عــن طريــق التهريــب قبــل شــهرين‬\n‫وأنــه قبــض عليــه بســبب قيامــه بالتســول وأن الطفــل هــو ابنــه وأمــه يف‬\n‫اليمــن وباســتجوابه أفــاد أنــه مينــي والطفــل الــذي معــه ابنــه ( ‪)........‬‬\n\n                                                                                            ‫‪232‬‬\n\f      ‫ودخــل بــه للمملكــة عــن الطريــق التهريــب قبــل شــهرين مــن القبــض‬\n      ‫عليــه ومت القبــض عليــه عندمــا كان يتســول يف أحــد املســاجد وبرفقتــه‬\n      ‫ابنــه وأضــاف أنــه ال يوجــد معــه أي اثبــات رســمي وأن ســبب دخولــه‬\n      ‫اململكــة وقيامــه بالتســول هــو كونــه يريــد مســاعدة ماليــة لعــاج‬\n      ‫ابنــه كونــه يعانــي مــن ضمــور يف العقــل وإعاقــة يف املشــي وأن زوجتــه‬\n      ‫وأهلــه يف اليمــن ومبواجهتــه بنتيجــة الفحــوص الوراثيــة أصــر علــى أن‬\n      ‫الطفــل الــذي برفقتــه ابنــه وقــد انتهــى التحقيــق إلــى  اتهــام املدعــى عليــه‬\n      ‫ب ــاإلجتار بطفــل يبلــغ ‪ 4‬ســنوات مســتغال ضعفــه باســتخدامه يف التســول‬\n      ‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬محضــر القبــض املتضمــن القبــض‬\n      ‫علــى املذكــور وبرفقتــه طفــل عمــره ‪ 4‬ســنوات وال يوجــد لديــه أي اثبــات‬\n      ‫رســمي يثبــت عالقــة الطفــل بــه املنــوه واملرفــق علــى اللفــة رقــم (‪. )2‬‬\n      ‫‪ -2‬إقــرار املذكــور بدخولــه البــاد بطريقــة غيــر نظاميــه مــع ابنــه (‬\n      ‫‪4........‬ســنوات) لطلــب املســاعدة املاليــة كــي يتمكــن مــن عــاج ابنــه‬\n      ‫وأنــه ال يوجــد لديــه أي رســمي لهويتــه وهويــة الطفــل املنــوه املــدون علــى‬\n      ‫اللفــة رقــم  (‪ )11-8‬وعلــى اللفــة رقــم (‪ )42-40‬وعلــى اللفــة رقــم (‪. )1‬‬\n      ‫‪ -3‬تقريــر الفحــوص الوراثيــة (‪  )DNA‬املتضمــن  أن املذكــور ليــس‬\n      ‫األب احلقيقــي للطفــل الــذي برفقتــه املنــوه املرفــق لفــة رقــم (‪)34-32‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرعا‬\n      ‫ـب عليــه شــرع ًا ومجـ ّـرم نظامــا وفــق مقتضــى املــادة‬   ‫فعــل محــرم ومعاقـ ٌ‬\n      ‫الثانيــة مــن نظــام مكافحــة االجتــار باألشــخاص الصــادر باملرســوم‬\n      ‫امللكــي رقــم م‪ 40/‬وتاريــخ ‪1430/7/21‬هــ  أطلــب اثبــات ادانتــه مبــا‬\n      ‫ُأســند إليــه واحلكــم عليــه بعقوبتــي الســجن والغرامــة وفــق مقتضــى‬\n      ‫املــادة الثالثــة مــن نظــام االجتــار باألشــخاص وتشــديد العقوبــة عليــه‬\n\n\n‫‪233‬‬\n\f‫وفــق مقتضــى الفقــرة الثالثــة مــن املــادة الرابعــة مــن النظــام نفســه وبــاهلل‬\n‫التوفيــق ويف هــذه اجللســة حضــر املدعــى عليــه‪ ........‬مبوجــب برنــت‬\n‫تفصيلــي عــن معلومــات ســجني صــادر ومصــدق مــن شــعبة إصالحيــة‬\n‫الدمــام املــدون بــه رقــم البطاقــة ‪........‬وأنــه مينــي اجلنســية وبعــرض دعــوى‬\n‫ا ‪ :‬الصحيــح أننــي بالفعــل كنــت أتســول‬       ‫املدعــي العــام عليــه أجــاب قائـ ً‬\n‫والطفــل املذكــور برفقتــي داخــل أحــد اجلوامــع حيــث أنــه بعــد االنتهــاء‬\n‫مــن صــاة العشــاء قمــت للمصلــن وشــرحت لهــم حــال هــذا الطفــل وأنــه‬\n‫يعانــي مــن ضمــور يف املــخ وأننــي أرغــب يف عالجــه ثــم ذهبــت عنــد بــاب‬\n‫املســجد أنتظــر املســاعدة مــن املصلــن ثــم مت القبــض علــي وهــذا االبــن‬\n‫هــو ابنــي ويدعــى ( ‪ )........‬وعمــره أربــع ســنوات وأربعــة أو خمســة أشــهر‬\n‫وهــو معــاق ال يســتطيع املشــي ويعانــي مــن ضمــو ٍر يف املــخ وغيــر صحيــح‬\n‫أنــه ليــس ابنــي وقــد دخلــت البــاد عــن طريــق التهريــب وكنــت أتســول‬\n‫داخــل املســاجد يف صالتــي املغــرب والعشــاء ملــدة شــهر يف جــده وملــدة‬\n‫عشــرة أيــام يف الدمــام هــذه إجابتــي وبســؤال املدعــي العــام هــل لديــه‬\n‫مزيــد بينــة علــى الدعــوى قــال ليــس لــدي مزيــد بينــة ســوى مــا ورد يف‬\n‫الئحــة الدعــوى وأوراق املعاملــة ثــم جــرى رفــع اجللســة للتأمــل احلمــد هلل‬\n‫وحــده وبعــد ويف يــوم األربعــاء املوافق‪1434/07/26‬ه ـ افتتحــت اجللســة‬\n‫ا ‪ :‬إن هنــاك شــخص‬       ‫وفيهــا حضــر الطرفــان وقــرر املدعــى عليــه قائ ـ ً‬\n‫يدعــى ( ‪ )........‬هــو مــن أحضرنــي إلــى الســعودية عــن طريــق التهريــب‬\n‫وهــو مــن كان يوصلنــي ألماكــن التســول ويقــوم بإرجاعــي وهــو الــذي‬\n‫قــام بتوفيــر الســكن لــي وبعــد أن يتــم إخــراج قيمــة اإليجار واملعيشــة من‬\n‫املبلــغ الــذي أحصــل عليــه بالتســول ُأعطيــه  ثلــث الباقــي مــن هــذا املبلــغ‬\n‫وقــد ســألت اآلن هــذا الشــخص فتــم إفادتــي أنــه مت ترحيلــه وال أعلــم‬\n\n\n                                                                                         ‫‪234‬‬\n\f      ‫عــن مــدى صحــة ذلــك فنظــر ًا ملــا تقــدم مــن الدعــوى واإلجابــة وحيــث‬\n      ‫أقــر املدعــى عليــه بالتســول حســب الطريقــة واملــدة التــي ذكرهــا يف‬\n      ‫جوابــه عــن الدعــوى وأقــر بــأن الطفــل الــذي كان معــه هــو ابنــه وحيــث‬\n      ‫ـار‬\n        ‫ال للطفــل املذكــور هــو يف حقيقتــه اجتـ ٌ‬     ‫أن تســول املدعــى عليــه مســتغ ً‬\n      ‫ـواء كان هــذا ابنــه أو غيــر ابنــه  وحيــث  أن املدعــى‬       ‫باألشــخاص سـ ً‬\n      ‫عليــه قــد قــام بالتســول بالطفــل املذكــور وهــو بذلــك قــد  اســتغل ضعفــه‬\n      ‫وصغــر ســنه وبعــد االطــاع علــى طيــات املعاملــة ومــن ضمنهــا تقريــر‬\n      ‫رقم‪........‬املرفــق علــى اللفــات رقــم ‪ ) 32-34‬مــن طيــات املعاملــة الصــادر‬\n      ‫مــن املختبــرات اجلنائيــة ‪/‬الفحــوص الوراثيــة بــإدارة األدلــة اجلنائيــة‬\n      ‫بشــرطة املنطقــة الشــرقية املتضمــن أن النتيجــة النهائيــة أن املقيــم ‪........‬‬\n      ‫ـاء علــى املــواد رقــم ( ‪ ) 1‬و ( ‪) 2‬‬   ‫ليــس األب احلقيقــي للطفــل ‪........‬وبنـ ً‬\n      ‫و ( ‪ ) 3‬و ( ‪  ) 4‬مــن نظــام االجتــار باألشــخاص صــادق املدعــى عليــه‬\n      ‫علــى دعــوى املدعــي العــام  فقــد  ثبــت لــدي إدانــة املدعــى عليــه باإلجتــار‬\n      ‫باألشــخاص عــن طريــق التســول بالطفــل املذكــور وقــررت تعزيــره علــى‬\n      ‫ـداء مــن تاريــخ إيقافــه كمــا أرى‬ ‫ذلــك للحــق العــام بالســجن ملــدة ســنة  ابتـ ً‬\n      ‫إبعــاد املدعــى عليــه عــن البــاد بعــد إنفــاذ مــا تقــرر شــرع ًا واســتيفاء مــا‬\n      ‫لــه ومــا عليــه مــن حقــوق وبعــرض احلكــم علــى الطرفــن قــرر املدعــى‬\n      ‫عليــه القناعــة وقــرر املدعــي العــام االعتــراض وطلــب رفــع احلكــم‬\n      ‫حملكمــة االســتئناف بالئح ـ ٍة اعتراضيــة مقدم ـ ًة منــه ف ُأجيــب لطلبــه‬\n      ‫وجــرى إفهامــه أن عليــه احلضــور يــوم الســبت ‪1434/7/29‬ه ـ الســتالم‬\n      ‫صــورة مــن احلكــم وأنــه يف التاريــخ املذكــور ســوف يتــم إيــداع القــرار‬\n      ‫ملــف الدعــوى وســوف يكــون ذلــك اإليــداع مجريـ ًا مليعــاد الثالثــن يومـ ًا‬\n      ‫يقــدم خاللهــا الئحتــه االعتراضيــة وأنــه مبضيهــا دون تقــدمي الالئحــة‬\n\n\n‫‪235‬‬\n\f‫ويرفــع احلكــم حملكمــة االســتئناف‬       ‫ســوف يســقط حقــه يف تقدميهــا ُ‬\n‫بدونهــا فامتثــل واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n‫وســلم احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافق‪1434/09/07‬ه ـ‬\n‫افتتحــت اجللســة وقــد انتهــت مــدة االعتــراض املنصــوص عليهــا يف املــادة‬\n‫رقــم ( ‪ ) 194‬مــن نظــام اإلجــراءات اجلزائيــة ولــم يســتلم املدعــي العــام‬\n‫صــورة احلكــم ولــم يقــدم الئحتــه االعتراضيــة وعليــه فقــد ســقط حقــه‬\n‫ـاء علــى املــادة‬\n                ‫يف تقدميهــا وســوف ُيرفــع احلكــم حملكمــة االســتئناف بنـ ً‬\n‫رقــم ( ‪ ) 195‬مــن نظــام اإلجــراءات اجلزائيــة واهلل املوفــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪ .‬احلمــد هلل وحــده وبعــد ويف‬\n‫يــوم االثنــن املوافق‪1434/12/16‬هــ  فتحــت اجللســة وقــد وردت املعاملــة‬\n‫مــن محكمــة االســتئناف باملنطقــة الشــرقية مبوجــب اخلطــاب رقــم‬\n‫‪ 342277135‬يف ‪1434/11/25‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة‬\n‫قضــاة الدائــرة اجلزائيــة الثانيــة مبحكمــة االســتئناف باملنطقــة الشــرقية‬\n‫رقــم ‪ 34353183‬يف ‪1434/11/6‬ه ـ املتضمــن املصادقــة علــى احلكــم‬\n‫لــذا جــرى إحلاقــه واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪236‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":231,"source_page_end":236,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8c793d8ee13e54ab16add3b9cdd01f6a5169d42748b372f072ae1d3314880add","normalized_text_hash":"03b2f58004d0f1fb4a774d9c96768c1b24e40bf6acc14f939e36ff765ae12b96","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p231-34284025"},{"id":"4349a6b9-930e-5191-9eaf-768426d3254e","document_type":"judgment","category":"judicial","subcategory":"general","title":"-فعل الفاحشة دون إياج -إساءة استخدام الهاتف النقال بتصوير فعل الفاحشة -حيازة مقطع جنسي -تعزير بالسجن واجللد والغرامة واملصادرة واإلتاف ،مع التوصية باإلبعاد.","document_number":"34315915","case_number":"34414600","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية على املعاملة املقيدة لدى المحكمة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/09/09","year":"1434","subject":"-فعل الفاحشة دون إياج -إساءة استخدام الهاتف النقال بتصوير فعل الفاحشة -حيازة مقطع جنسي -تعزير بالسجن واجللد والغرامة واملصادرة واإلتاف ،مع التوصية باإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34315915:‬تاريخه‪1434/09/09 :‬هـ‬\n                          ‫رقم الدعوى‪34414600:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34343526‬تاريخه‪1434/10/28:‬هـ‬\n\n\n       ‫اجتــار باألشــخاص عــن طريــق نقــل وإيــواء امرأتــن والسمســرة عليهمــا‬\n       ‫‪ -‬فعــل الفاحشــة دون إيــاج‪ -‬إســاءة اســتخدام الهاتــف النقــال بتصويــر‬\n       ‫فعــل الفاحشــة ‪ -‬حيــازة مقطــع جنســي‪ -‬تعزيــر بالســجن واجللــد‬\n                      ‫والغرامــة واملصــادرة واإلتــاف ‪ ،‬مــع التوصيــة باإلبعــاد‪.‬‬\n\n\n\n\n        ‫‪ -‬قول اهلل تعالى ((وال تقربوا الزنا إنه كان فاحشة وساء سبيال))‪.‬‬\n             ‫‪ -‬وقوله تعالى ((وال تقربوا الفواحش ما ظهر منها وما بطن))‪.‬‬\n       ‫‪ -‬املــادة األولــى‪ ،‬والثالثــة‪ ،‬والرابعــة‪ ،‬مــن نظــام مكافحــة االجتــار‬\n                                                                ‫باأل شــخاص‪.‬‬\n       ‫‪ -‬املادتــان الثالثــة‪ ،‬والثالثــة عشــرة مــن نظــام مكافحــة جرائــم‬\n                                                                  ‫ا ملعلو ما تيــة ‪.‬‬\n\n\n\n\n       ‫انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه باإليــواء وفعــل‬\n       ‫الفاحشــة واالجتــار باألشــخاص وحيــازة مقطــع جنســي يف جهــازه‬\n       ‫اجلــوال ‪ ،‬وذلــك بعــد القبــض علــى املدعــى عليــه إثــر بــاغ مفــاده قيامــه‬\n       ‫بامتهــان تهريــب العامــات وإيوائهــن‪ -‬طلــب املدعــي العــام احلكــم عليــه‬\n       ‫بعقوبــة تعزيريــة لقيامــه باإلجتــار باألشــخاص وإيــواء اخلادمــات مبوجــب‬\n\n‫‪237‬‬\n\f  ‫املــادة الثالثــة مــن نظــام  مكافحــة جرائــم االجتــار باألشــخاص وتشــديد‬\n  ‫العقوبــة عليــه وفــق املــادة الرابعــة مــن ذات النظــام وكذلــك تعزيــره‬\n  ‫لقــاء قيامــه بفعــل الفاحشــة وحيــازة مقاطــع إباحيــة يف جوالــه‪ -‬بعــرض‬\n  ‫دعــوى املدعــي العــام علــى املدعــى عليــه بواســطة املترجــم صــادق علــى‬\n‫إيــواء خادمتــن هاربتــن‪ ،‬وتشــغيلهما وأخــذ مبالــغ ماليــة مقابــل ذلــك‪  ،‬‬\n  ‫كمــا صــادق علــى فعــل الفاحشــة دون إيــاج وأنــه قــام بتصويــر نفســه‬\n  ‫باجلــوال أثنــاء فعــل الفاحشــة‪ -‬نظــر ًا ألن املدعــى عليــه أقــر باتفاقــه مــع‬\n  ‫إحــدى العامــات املنزليــات علــى أن تهــرب مــن كفيلهــا وقيامــه بنقــل‬\n  ‫هــذه العاملــة وكذلــك نقــل وإيــواء عاملــة منزليــة أخــرى هاربــة مــن‬\n  ‫كفيلهــا وذلــك ألجــل أن تعمــل هاتــان العاملتــان لــدى أشــخاص آخريــن‬\n  ‫ويســتفيد املدعــى عليــه ماديـ ًا مــن ذلــك وهــذا مــن إســاءة االســتغالل وهــو‬\n  ‫مــن االجتــار باألشــخاص‪ ،‬وألنــه أقــر باختالئــه بإحــدى النســاء وفعــل‬\n  ‫الفاحشــة بهــا دون إيــاج كمــا أقــر بقيامــه بتصويــر نفســه باجلــوال‬\n  ‫مبقطــع فيديــو مــع املــرأة وهمــا يفعالن الفاحشــة وهذا مــن اإلصرار على‬\n  ‫املعصيــة وهــو مــن اجلرائــم املعلوماتيــة‪ ،‬لــذا ثبــت ارتــكاب املدعــى عليــه‬\n  ‫جلرميــة االجتــار باألشــخاص وذلــك بقيامــه بنقــل امرأتــن هاربتــن مــن‬\n  ‫العمــل لــدى كفليهمــا وإيــواء إحداهمــا مــن أجــل إســاءة االســتغالل ومت‬\n  ‫احلكــم بتعزيــر املدعــى عليــه بســجنه مــدة ســنتني وتغرميــه مبلــغ عشــرة‬\n  ‫آالف ريــال كمــا ثبــت ارتــكاب املدعــى عليــه جلرميــة معلوماتيــة وذلــك‬\n  ‫بقيامــه بإســاءة اســتخدام هاتفــه النقــال املــزود بالكاميــرا بتصويــره‬\n  ‫نفســه وهــو يفعــل الفاحشــة مــع إحــدى النســاء ومت احلكــم بتعزيــره‬\n  ‫لقــاء ذلــك بســجنه مــدة ســتة أشــهر وتغرميــه مبلــغ خمســة آالف ريــال‬\n  ‫ومصــادرة هاتفــه اجلــوال املســتخدم يف اجلرميــة وإتالفــه كمــا  ثبــت قيــام‬\n\n\n                                                                                         ‫‪238‬‬\n\f      ‫املدعــى عليــه باالختــاء بإحــدى النســاء وفعــل الفاحشــة معهــا دون إيــاج‬\n      ‫ومت احلكــم بتعزيــره بســجنه مــدة عشــرة أشــهر وجلــده تســعني جلــده‬\n      ‫علــى دفعتــن متســاويتني مــع التوصيــة بإبعــاد املدعــى عليــه عــن البــاد‪-‬‬\n      ‫بعــرض احلكــم قنــع املدعــى عليــه ولــم يقنــع املدعــي العــام مكتفيـ ًا مبــا‬\n      ‫قــدم يف الئحــة الدعــوى‪ ،‬وبعــد رفــع احلكــم حملكمــة االســتئناف متــت‬\n                                                                        ‫املصادقــة عليــه ‪.‬‬\n\n\n\n\n        ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد لــدي أنــا‬\n        ‫‪........‬القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا‬\n      ‫من فضيلة رئيس احملكمة اجلزائية يف محافظة اخلبر برقم ‪  34414600‬‬\n        ‫وتاريــخ ‪1434/09/07‬ه ـ املقيــدة باحملكمة برقــم ‪ 342136171‬وتاريخ‬\n        ‫‪ 1434/09/07‬هــ  ففــي يــوم  الثالثــاء املوافــق‪ 1434/09/08‬هـ افتتحت‬\n        ‫اجللســة الســاعة ‪  10 : 30‬وفيهــا قــدم املدعــي العــام ‪........‬الئحــة دعــوى‬\n        ‫عامــه ضــد ‪........‬بنجالديشــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n        ‫ا فيهــا انــه بتاريــخ ‪1434/7/11‬ه ـ ورد بــاغ لشــرطة محافظــة‬            ‫‪........‬قائـ ً‬\n        ‫اخلبــر عــن قيــام املتهــم ‪ ......../‬بنجالديشــي اجلنســية بامتهــان تهريــب‬\n        ‫العامــات وإيوائهــن وقــد مت عمــل كمــن للمتهــم املذكــور ومت القبــض‬\n        ‫وأفــاد الفرقــة بأنــه يعمــل علــى إيــواء اخلادمــات وتهريبهــم وتوظيفهــم‬\n        ‫مقابــل مبالــغ ماليــة وكذلــك وجــد يف جوالــه بحوزتــه علــى صــور  لعاملــة‬\n        ‫منزليــة وهــو يقــوم مبمارســة الفاحشــة معهــا بســماع أقــوال املتهــم ‪ /‬أقــر‬\n        ‫بقيامــه بأخــذ اخلادمــة لتعمــل عنــد ‪ ........‬وأنــه قــام باالتصــال عليهــا‬\n        ‫وهربــت وقابلهــا علــى طريــق الكورنيــش ب‪ .....‬وباســتجواب املتهــم‪/‬‬\n\n‫‪239‬‬\n\f  ‫أنكــر انــه يقــوم بإيــواء اخلادمــات وإمنــا كان ميشــي بســيارته فوجــد‬\n  ‫خادمــه متشــي فقــام بإركابهــا وطلبــت منــه أن تعمــل فذهــب بهــا إلــى‬\n  ‫امــرأة تدعى‪........‬وبعــد عشــرة أيــام اتصلــت بــه املــرأة وأفــادت أنهــا ال‬\n  ‫تريدهــا وطلبــت منــه أن يأخذهــا فتــم القبــض عليــه وبســؤاله عن املقاطع‬\n  ‫املوجــودة يف جوالــه والتــي ميــارس فيهــا فعــل الفاحشــة مــع خادمــة ذكــر‬\n  ‫بأنهــا خادمــة كفيلــه وانــه فعــل معهــا الفاحشــة مفاخــذة وذلــك قبــل‬\n  ‫خمــس ســنوات وأنكــر أن يكــون قــد طلــب مــن اخلادمــة الهــروب مــن‬\n  ‫كفيلهــا وبســؤاله عــن قبضــه ملبلــغ مالــي مقابــل إحضــار خادمــات للعمل‬\n  ‫يف املنــازل أجــاب بأنــه أخــذ مبلــغ ثالثــة االف مــن ‪........‬وبعــد عشــرة أيــام‬\n  ‫أعادهــا لــه الن العاملــة ال تصلــح وأنكــر ان يكــون علــى عالقــة ســابقة‬\n‫باخلادمــة أو ميتهــن تشــغيل العامــات انتهــى التحقيــق إلــى توجيــه االتهــام  ‬\n  ‫‪ ........‬باإليــواء وفعــل الفاحشــة واالجتــار باألشــخاص وحيــازة مقطــع‬\n  ‫جنســي يف جهــاز اجلــوال وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬محضــر‬\n  ‫ســماع األقــوال ‪ -2‬محضــر مشــاهدة يف ملــف ســماع األقــوال ‪ -3‬اقــرار‬\n  ‫املتهــم بإيــواء اخلادمــة وتهريبهــا مــن كفيلهــا لكــي تعمــل يف مــكان‬\n  ‫اخــر وذلــك يف محضــر ســماع األقــوال  ‪ -4‬مــا ورد يف محضــر القبــض‬\n  ‫املعــد مــن فرقــة البحــث اجلنائــي وحيــث إن مــا أقــدم عليــه املذكــور وهــو‬\n  ‫بكامــل أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب‬\n  ‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــر‬\n  ‫لقيامــه باإلجتــار باألشــخاص وإيــواء اخلادمــات مبوجــب املــادة الثالثــة‬\n  ‫مــن نظــام  مكافحــة جرائــم االجتــار باألشــخاص وتشــديد العقوبــة‬\n  ‫عليــه وفــق املــادة الرابعــة مــن ذات النظــام وكذلــك تعزيــره لقــاء قيامــه‬\n  ‫بفعــل الفاحشــة وحيــازة مقاطــع إباحيــة يف جوالــه هــذه دعــواي وبســؤال‬\n\n\n                                                                                           ‫‪240‬‬\n\f      ‫املدعــى عليــه عــن الدعــوى بواســطة املترجــم املتعــاون ‪........‬أجــاب بقولــه‬\n      ‫الصحيــح أنــه قبــل القبــض علــي بشــهر اتصلــت بــي امــرأة مــن اجلنســية‬\n      ‫االندونيســية تعمــل يف أحــد املنــازل وذكــرت بــأن تعامــل كفيلهــا غيــر‬\n      ‫جيــد وطلبــت منــي تأمــن عمــل لــدى أســرة أخــرى فاتفقــت معهــا عــل أن‬\n      ‫تهــرب مــن كفيلهــا ويتــم مقابلتهــا بالقــرب مــن كورنيــش اخلبــر وبالفعل‬\n      ‫هربــت هــذه املــرأة مــن كفيلهــا وقابلتهــا جــوار الكورنيــش وركبــت‬\n      ‫معــي يف الســيارة وذهبــت بهــا إلــى امــرأة تدعى‪........‬تســكن يف شــقة‬\n      ‫بحــي ‪........‬باخلبــر كانــت تبحــث عــن عاملــة منزليــة وقــد أعطتنــي ‪........‬‬\n      ‫مبلــغ ثالثــة االف ريــال لقــاء إحضــاري هــذه العاملــة لهــا  كمــا ســبق لــي‬\n      ‫قبــل ســنتني تقريبـ ًا أن قابلــت عاملــة منزليــة هاربــة مــن كفيلهــا يف حــي‬\n      ‫‪........‬باخلبــر وذهبــت بهــا إلــى شــقة مفروشــة تعــود لصديــق لــي حيــث مت‬\n      ‫التنســيق معــه وبقيــت هــذه العاملــة يف الشــقة مــدة ســاعتني تقريبـ ًا حيــث‬\n      ‫اتصلــت بامــرأة تدعــى ‪........‬وعرضــت عليهــا أن تعمــل لديهــا هــذه العاملة‬\n      ‫املنزليــة فوافقــت فقمــت بتوصيــل هــذه العاملــة املنزليــة لســكن ‪........‬‬\n      ‫وهــو شــقة يف الدمــام واســتلمت مــن ‪........‬لقــاء ذلــك مبلــغ مائتــي ريــال‬\n      ‫‪ 200‬ومــا ذكــره املدعــي العــام مــن فعلــي الفاحشــة دون إيــاج فهــذا‬\n      ‫صحيــح وكان ذلــك قبــل خمــس ســنوات تقريبـ ًا حيــث كنــت أســكن‬\n      ‫يف غرفــة داخــل منــزل كفيلــي بحــي ‪........‬بالدمــام وتعرفــت علــى العاملة‬\n      ‫املنزليــة لــدى كفيلــي واختليــت بهــا يف غرفتــي وفعلــت معهــا الفاحشــة‬\n      ‫دون إيــاج وقمــت بتصويــر نفســي باجلــوال وأنــا أفعــل الفاحشــة مــع هــذه‬\n      ‫املــرأة وبعــد القبــض علــي وجــد رجــال األمــن يف جهــاز جوالــي وهــو نــوع‬\n      ‫‪ .....‬مقطــع الفيديــو الــذي أظهــر بــه مــع العاملــة املنزليــة ونحــن نفعــل‬\n      ‫الفاحشــة هــذا مــا حصــل هكــذا أجــاب ثــم أقفلــت اجللســة الســاعة‬\n\n\n‫‪241‬‬\n\f‫احلاديــة عشــر والنصــف للتأمــل وصلــى اهلل وســلم علــى نبينــا محمــد‬\n‫احلمــد هلل وحــده وبعــد ثــم إنــه يف هــذا اليــوم األربعــاء ‪1434/9/9‬ه ـ‬\n‫الســاعة العاشــرة افتتحــت اجللســة بحضــور املدعــى عليه‪........‬وجــرى‬\n‫ســؤاله هــل أنــت محصــن فأجــاب بقولــه إنــي غيــر محصــن فلــم يســبق‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬   ‫لــي الــزواج هكــذا قــرر فبنـ ً‬\n‫وحيــث أقــر املدعــى عليــه باتفاقــه مــع إحــدى العامــات املنزليــة علــى‬\n‫أن تهــرب مــن كفيلهــا وقيامــه بنقــل هــذه العاملــة وكذلــك نقــل وإيــواء‬\n‫عاملــة منزليــة أخــرى هاربــة مــن كفيلهــا وذلــك ألجــل أن تعمــل هاتــان‬\n‫العاملتــان لــدى أشــخاص آخريــن ويســتفيد املدعــى عليــه ماديـ ًا مــن ذلــك‬\n‫وهــذا مــن إســاءة االســتغالل وهــو مــن االجتــار باألشــخاص حســب مــا‬\n‫جــاء يف املــادة األولــى مــن نظــام مكافحــة االجتــار باألشــخاص وحيــث‬\n‫أقــر املدعــى عليــه باختالئــه بإحــدى النســاء وفعــل الفاحشــة بهــا دون‬\n‫إيــاج ولقــول اهلل تعالــى ((وال تقربــوا الزنــا إنــه كان فاحشــة وســاء‬\n‫ســبيال))وقوله عــز وجــل ((وال تقربــوا الفواحــش مــا ظهــر منهــا ومــا‬\n‫بطن))كمــا أقــر بقيامــه بتصويــر نفســه باجلــوال مبقطــع فيديــو مــع‬\n‫املــرأة وهمــا يفعــان الفاحشــة وهــذا مــن االصــرار علــى املعصيــة وهــو‬\n‫مــن اجلرائــم املعلوماتيــة وملــا جــاء يف املادتــن الثالثــة والرابعــة مــن نظــام‬\n‫مكافحــة االجتــار باألشــخاص واملادتــن الثالثــة والثالثــة عشــرة مــن‬\n‫نظــام مكافحــة جرائــم املعلوماتيــة لــذا فقــد قــررت مــا يلــي أو ًال ثبــت‬\n‫لــدي ارتــكاب املدعــى عليــه جلرميــة االجتــار باألشــخاص وذلــك بقيامــه‬\n‫بنقــل امرأتــن هاربتــن مــن العمــل لــدى كفالئهمــا وايــواء احداهمــا مــن‬\n‫أجــل اســاءة االســتغالل وقــررت تعزيــر املدعــى عليــه لقــاء فعلــه بســجنه‬\n‫مــدة ســنتني وتغرميــه مبلــغ عشــرة االف ريــال ثاني ـ ًا ثبــت لــدي ارتــكاب‬\n\n\n                                                                                          ‫‪242‬‬\n\f      ‫املدعــى عليــه جلرميــة معلوماتيــة وذلــك لقيامــه بإســاءة اســتخدام هاتفــه‬\n      ‫النقــال املــزود بالكاميــرا بتصويــره نفســه وهــو يفعــل الفاحشــة مــع‬\n      ‫احــدى النســاء وقــررت تعزيــره لقــاء ذلــك بســجنه مــدة ســتة أشــهر‬\n      ‫وتغرميــه مبلــغ خمســة االف ريــال ومصــادرة هاتفــه اجلــوال املســتخدم يف‬\n      ‫اجلرميــة واتالفــه ثالث ـ ًا ثبــت لــدي قيــام املدعــى عليــه باالختــاء بإحــدى‬\n      ‫النســاء وفعــل الفاحشــة معهــا دون إيــاج وقــررت تعزيــر املدعــى عليــه‬\n      ‫لقــاء ذلــك بســجنه مــدة عشــرة أشــهر وجلــده تســعني جلــده علــى دفعتــن‬\n      ‫متســاويتني بينهمــا مــدة ال تقــل عــن عشــرة أيــام وبذلــك يكــون مجمــوع‬\n      ‫ســجن املدعــى عليــه هــو ثــاث ســنوات وأربعــة أشــهر اعتبــار ًا مــن تاريــخ‬\n      ‫إيقافــه ومبــا تقــدم حكمــت وأوصيــت بإبعــاد املدعــى عليــه عــن البــاد‬\n      ‫فــور انتهــاء محكوميتــه بعــد انهــاء مــا لــه وعليــه مــن حقــوق اتقــاء لشــره‬\n      ‫وبعــرض احلكــم قنــع املدعــى عليــه ولــم يقنــع املدعــي العــام مكتفيـ ًا مبا‬\n      ‫قــدم يف الئحــة الدعــوى وأقفلــت اجللســة الســاعة احلاديــة عشــر اال ثلــث‬\n      ‫وقــد متــت الترجمــة بواســطة املترجــم املتعــاون ‪........‬وصلــى اهلل وســلم‬\n                                                                       ‫علــى نبينــا محمــد ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪/34/2206230‬ج‪ 2‬وتاريــخ ‪1434/9/17‬ه ـ‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم‬\n      ‫‪ 34/2136171‬وتاريــخ ‪1434/9/10‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشيخ‪......../‬املســجل برقــم ‪34315915‬‬\n      ‫وتاريــخ ‪1434/9/9‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪......../‬‬\n      ‫(بنجالديشــي اجلنســية) يف قضيــة فعــل الفاحشــة واالجتــار باألشــخاص‬\n\n\n‫‪243‬‬\n\f‫وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبه وســلم‪.‬‬\n                                                  ‫حــرر يف ‪1434/9/28‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                 ‫‪244‬‬\n\f245\n\f246\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"de1f53c6-ba9d-56f0-bb6e-3334ff0b129a","source_page_start":237,"source_page_end":246,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6c8615bdda381a151173be902d70518e8eb51e72b78055cb8cba679ac20be8ab","normalized_text_hash":"60ac7575ed53b6e45a528799d4aa2607c3de6e7cd9b25ca5df73bdc1219fbeea","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v22-p237-34315915"},{"id":"f8d52d4f-9649-5005-a93b-a263cf00d446","document_type":"judgment","category":"judicial","subcategory":"general","title":"حرق -اتاف ملك الغير -احراق سيارة وإغاق التيار الكهربائي -دعوى عامة وخاصة -إقرار املدعى عليه -تنازل عن حق خاص -ثبوت إدانة -وجود سوابق قضائية -تعزير بالسجن واجللد وإيداعه دار الرعاية االجتماعية ما أشار له القاضي يف تسبيب احلكم.","document_number":"34188767","case_number":"3411199","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعرعر","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/15","year":"1434","subject":"حرق -اتاف ملك الغير -احراق سيارة وإغاق التيار الكهربائي -دعوى عامة وخاصة -إقرار املدعى عليه -تنازل عن حق خاص -ثبوت إدانة -وجود سوابق قضائية -تعزير بالسجن واجللد وإيداعه دار الرعاية االجتماعية ما أشار له القاضي يف تسبيب احلكم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"               ‫رقم الصك ‪ 34188767 :‬تاريخه‪:‬‬\n          ‫‪1434/4/15‬هـ رقم الدعوى‪3411199:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪        34206074‬تاريخه‪1434/5/5 :‬هـ‬\n\n\n      ‫حــرق ‪ -‬اتــاف ملــك الغيــر ‪ -‬احــراق ســيارة وإغــاق التيــار الكهربائــي‬\n      ‫‪ -‬دعــوى عامــة وخاصــة ‪ -‬إقــرار املدعــى عليــه ‪ -‬تنــازل عــن حــق خــاص‬\n      ‫‪ -‬ثبــوت إدانــة ‪ -‬وجــود ســوابق قضائيــة ‪ -‬تعزيــر بالســجن واجللــد‬\n                                             ‫وإيداعــه دار الرعايــة االجتماعيــة‬\n\n\n\n\n                                          ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n      ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بإحــراق ســيارة‬\n      ‫مواطــن وإغــاق التيــار الكهربائــي عنــه وطلــب إثبــات مــا أســند إليــه‬\n      ‫وإيقــاع العقوبــة التعزيريــة عليــه حيــث ورد تقريــر مــن الدوريــات األمنيــة‬\n      ‫باحتراق ســيارة ومشــاهدة املدعى عليه قريبا منها وهروبه ملا شــاهدها‬\n      ‫وبالقبــض عليــه عثــر بحوزتــه علــى والعتــن كمــا تقــدم املدعــي اخلــاص‬\n      ‫بشــكوى ضــده بقيامــه بإحــراق ســيارته وإغــاق التيــار الكهربائــي‬\n      ‫عليــه ‪ ،‬أقــر املدعــى عليــه بقيامــه بإغــاق التيــار الكهربائــي عــن‬\n      ‫املدعــي اخلــاص وأنكــر قيامــه بإحــراق ســيارته ‪ ،‬جــرى ســؤاله عــن‬\n      ‫الدافــع لقيامــه بإغــاق التيــار الكهربائــي عــن املدعــي اخلــاص فأجــاب‬\n      ‫بأنــه ال يعلــم مــا الدافــع لكونــه مريضــا ويفقــد الوعــي أحيانــا ويتصــرف‬\n\n‫‪247‬‬\n\f‫تصرفــات ال يعلمهــا ‪ ،‬حضــر املدعــي اخلــاص وقــرر تنازلــه عــن املدعــى‬\n‫عليــه ‪ -‬أقــر املدعــى عليــه بــأن عليــه خمــس عشــرة ســابقة كلهــا شــرب‬\n‫مســكر عــدا ســابقة واحــدة مشــابهة للدعــوى املقامــة ضــده ‪ ،‬أقــر‬\n‫املدعــى عليــه بأنــه يبلــغ مــن العمــر ســبعني ســنة وأنــه غيــر متــزوج وليــس‬\n‫لديــه أوالد ‪ ،‬وإلقــرار املدعــى عليــه وألن فعلــه يعــد اســتخفافا بأمــوال‬\n‫الغيــر ولكثــرة ســوابقه ولكبــر ســنه ولعــدم ارتداعــه بالعقوبــات‬\n‫الســابقة وخلطــره علــى نفســه وعلــى املجتمــع ولتنــازل املدعــي اخلــاص ‪،‬‬\n‫لــذا قــررت احملكمــة مــا يلــي ‪ :‬أو ًال ‪ /‬ثبــوت تنــازل املدعــي اخلــاص عــن‬\n‫حقــه جتــاه املدعــى عليــه‪ .‬ثاني ـ ًا ‪ /‬ثبــوت إدانــة املدعــى عليــه مبــا نســب‬\n‫إليــه يف الئحــة االدعــاء العــام وتعزيــره ألجلــه ولكثــرة ســوابقه حكمــت‬\n‫احملكمــة بســجنه ســنة مــن تاريــخ إيقافــه وجلــده مئــة وعشــرين جلــدة‬\n‫مفرقــة علــى دفعتــن بــن كل دفعــة وأخــرى خمســة عشــر يومــا‪ .‬ثالثــا‪/‬‬\n‫إيــداع املدعــى عليــه الرعايــة االجتماعيــة بعــد انتهــاء مــدة الســجن حمايــة‬\n‫للمجتمــع مــن شــره ‪ ،‬قــرر الطرفــان عــدم القناعــة ‪ ،‬صــدق احلكــم مــن‬\n                                                            ‫محكمــة االســتئناف‪.‬‬\n\n\n\n‫اجلزائيــة‬\n   ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..............‬رئيــس احملكمــة‬\n‫بســكاكا وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪ 3411199‬وتاريــخ‬\n‫‪1434/01/07‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3446657‬وتاريــخ‬\n‫‪1434/01/06‬ه ـ ففــي يــوم األربعــاء املوافق‪1434/01/14‬ه ـ افتتحــت‬\n‫اجللســة األولــى يف متــام الســاعة ‪ 09 : 00‬وفيهــا قــدم املدعــي العــام‬\n‫تركــي بــن صالــح اجلاســر الئحــة دعوى عامة ضــد ‪ ................ /‬ســعودي‬\n\n                                                                                       ‫‪248‬‬\n\f      ‫بالســجل املدنــي رقــم ‪ .............‬قائــا فيهــا إنــه بتاريــخ ‪1433/12/20‬ه ـ‬\n      ‫ورد ملركــز شــرطة ‪ ......‬تقريــر دوريــات األمــن رقــم (‪ )6946‬املتضمــن‬\n      ‫مالحظــة ســيارة بحــي ‪ .......‬مشــتعلة وفــرار املتهــم الــذي كان بجانبهــا‬\n      ‫بعــد مشــاهدة الدوريــة وقــد مت ضبطــه وتفتيشــه فوجــد بحوزتــه والعتــن‬\n      ‫وجــوال‪ .‬كمــا تقــدم ‪ ........... /‬بدعــوى مفادهــا إحــراق املتهــم ســيارته‬\n      ‫وإطفــاء كهربــاء منزلــه‪ .‬وبســماع أقــوال املدعــي أفــاد بحضــور املتهــم‬\n      ‫ملنزلــه وإطفــاء الكهربــاء وعنــد خروجــه مــن املنــزل شــاهد ســيارته‬\n      ‫حتتــرق‪ .‬ومبعاينــة املوقــع مــن قبــل رجــل الضبــط اجلنائــي وجــد ســيارة‬\n      ‫مــن نــوع ‪ .........‬موديــل ‪ ......‬لوحــة رقــم ‪ .......‬اتضــح وجــود احتــراق بغمــارة‬\n      ‫الســيارة ومؤخــرة الســيارة كمــا مت معاينــة الســيارة الثانيــة مــن نــوع‬\n      ‫‪ ......‬موديــل ‪ .....‬واتضــح أن لوحاتهــا منزوعــة مــن مواقعهــا والثانيــة‬\n      ‫مطعوجــة وكالهمــا مرميتــان يف حاويــة النفايــات‪ .‬وباســتجواب املتهــم‬\n      ‫أقــر بإطفــاء كهربــاء منــزل املدعــي ونفــى إحــراق الســيارة‪ .‬وانتهــى‬\n      ‫التحقيــق إلــى توجيــه االتهــام ل ـ ‪ .......... /‬بإحــراق ســيارة ‪ ..........‬مــن نــوع‬\n      ‫‪ .......‬موديــل ‪ ........‬لوحــة رقــم ‪ .........‬وإطفــاء كهربــاء منزلــه‪ .‬وحيــث إن‬\n      ‫مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم‬\n      ‫ومعاقــب عليــه شــرعا ممــا يتعــن معــه إحالتــه إلــى احملكمــة اجلزئيــة‬\n      ‫اســتنادا إلــى املادتــن (‪ 126‬و ‪ )128‬مــن نظــام اإلجــراءات اجلزائيــة فإننــي‬\n      ‫أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n      ‫تزجــره وتــردع غيــره والتشــديد عليــه لقــاء تعــدد ســوابقه‪( .‬علمــا بــأن‬\n      ‫احلــق اخلــاص ال يــزال قائــم) هــذه دعــواي وبعــرض دعــوى املدعــي العــام‬\n      ‫علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام مــن أننــي قمــت‬\n      ‫بإقفــال عــداد الكهربــاء علــى منــزل جــاري فهــذا صحيــح وأمــا مــا ذكر‬\n      ‫املدعــي العــام مــن أننــي قمــت بإحــراق ســيارة جــاري فهــذا غيــر صحيــح‬\n‫‪249‬‬\n\f‫وال أعلــم مــن قــام بإحــراق الســيارة وصحيــح أننــي كنــت موجــودا بقــرب‬\n‫الســيارة ثــم ذهبــت إلــى منزلــي وكان بحوزتــي والعتــن ألننــي أســتعمل‬\n‫الدخــان هكــذا أفــاد هــذا وقــد جــرى ســؤال املدعــى عليــه عــن ســبب‬\n‫إقفــال عــداد الكهربــاء علــى جــاره قــال ال أعلــم عــن ذلــك وأنــا مريــض‬\n‫وبعــض األحيــان أفقــد الوعــي وأتصــرف بتصرفــات ال أعلمهــا هكــذا‬\n‫أفــاد وبطلــب البينــة مــن املدعــي العــام علــى أن املدعــى عليــه قــام بإحــراق‬\n‫الســيارة اخلاصــة باملدعــي ‪ .....‬قــال بينتــي هــي مــا جــاء يف محضــر القبض‬\n‫ومــا جــاء مــن وجــود املدعــى عليــه يف مســرح اجلرميــة ووجــود والعتــن معــه‬\n‫هكــذا أفــاد هــذا وقــد جــرى االطــاع علــى أوراق املعاملــة فوجــدت مــن‬\n‫بــن طياتهــا محضــر القبــض املــدون علــى اللفــة الثالثــة وباالطــاع علــى‬\n‫احملضــر وجدتــه كمــا ذكــر املدعــي العــام يف  دعــواه وبعــرض ذلــك‬\n‫علــى املدعــى عليــه مــا جــاء يف محضــر القبــض غير صحيح هكــذا أفاد‬\n‫لــذا جــرى طلــب معــدي محضــر القبــض ورفــع اجللســة إلــى يــوم األربعــاء‬\n‫‪1434/02/06‬ه ـ الســاعة التاســعة وعليــه جــرى التوقيــع وأقفلت اجللســة‬\n‫يف متــام الســاعة التاســعة والنصــف حــرر يف ‪1434/01/14‬ه ـ وبــاهلل‬\n‫التوفيــق ويف هــذا اليــوم االثنني املوافق‪1434/02/25‬هـ افتتحت اجللســة‬\n‫الثالثــة يف متــام الســاعة ‪ 09:30‬وفيهــا لــم يحضــر املدعــى عليــه وحضــر‬\n‫يف هــذه اجللســة ‪ ..........‬ســعودي بالســجل املدنــي رقــم ‪ ..........‬وبســؤاله‬\n‫عمــا لديــه مــن شــهادة قــال أشــهد هلل أننــي كنــت يف دوريــة ســرية‬\n‫فشــاهدت رجــل كبيــر الســن يدعــى ‪ .....‬متوقفــا عنــد ســيارة ‪ ........‬ملــا‬\n‫شــاهدني هــرب ثــم احترقــت الســيارة فلمــا تابعتــه وأخبــرت الدوريــات‬\n‫باحلادثــة مت القبــض عليــه وبتفتيشــه وجدنــا معــه والعتــن ومت إعــداد‬\n‫محضــر بذلــك هــذا مــا لــدي وبــه أشــهد كمــا حضــر ‪ .........‬ســعودي‬\n‫بالســجل املدنــي رقــم ‪ ..........‬وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد‬\n                                                                                        ‫‪250‬‬\n\f      ‫هلل أنــه وردت إلينــا إخباريــة مــن أن شــخصا قــام بإحــراق ســيارة فطلبــت‬\n      ‫منــا الدوريــة الســرية املســاعدة فحضرنــا إلــى املوقــع فوجدنــا شــخصا‬\n      ‫كبيــرا يف الســن حاســر الــرأس فتــم القبــض عليــه وبتفتيشــه وجدنــا‬\n      ‫معــه والعتــن علمــا أننــي لــم أشــاهد الرجــل أثنــاء إحــراق الســيارة بــل‬\n      ‫قبضنــا عليــه يف الشــارع اآلخــر وتســليمه إلــى مركــز شــرطة ‪.......‬‬\n      ‫هــذا مــا لــدي وبــه أشــهد لــذا جــرى رفــع اجللســة إلحضــار املدعــى عليــه‬\n      ‫وإبــاغ الشــاهد ‪ ..........‬باحلضــور وذلــك يــوم االثنــن ‪1434/03/02‬ه ـ‬\n      ‫الســاعة التاســعة والنصــف‪ .‬حــرر يف ‪1434/2/25‬ه ـ ‪ .‬ويف هــذا اليــوم‬\n      ‫االثنــن املوافق‪1434/04/15‬ه ـ افتتحــت اجللســة السادســة يف متــام‬\n      ‫الســاعة ‪ 09:00‬وفيهــا حضــر املدعــى عليــه وبعــرض شــهادة الشــاهد‬\n      ‫علــى املدعــى عليــه قــال مــا جــاء يف شــهادة الشــاهد صحيــح فإننــي قمــت‬\n      ‫بإشــعال النــار بســيارة جــاري وإطفــاء عــداد الكهربــاء وذلــك بســبب‬\n      ‫وجــود خــاف بســيط بينــي وبــن جــاري هكــذا أفــاد هذا وقــد حضر يف‬\n      ‫هــذه اجللســة املدعــي باحلــق اخلــاص ‪ ..........‬ســعودي بالســجل املدنــي رقــم‬\n      ‫‪ ........‬وقــرر قائــا إن هــذا احلاضــر أحــد جيرانــي وحصــل ســوء تفاهــم‬\n      ‫بينــي وبينــه وقــام هــذا احلاضــر بعــد منتصــف الليــل بإحــراق ســيارتي‬\n      ‫وإطفــاء عــداد الكهربــاء وإننــي أقــرر تنازلــي عــن حقــي اخلــاص لوجــه‬\n      ‫اهلل تعالــى وال أطالــب هــذا احلاضــر ال حاضــرا وال مســتقبال يف قيمــة‬\n      ‫تلفيــات ســيارتي هكــذا قــرر وكان ذلــك بحضــور العســكري املرافــق‬\n      ‫للســجني ‪ ..........‬ســعودي بالســجل املدنــي رقــم ‪ ..........‬و ‪ .........‬ســعودي‬\n      ‫بالســجل املدنــي رقــم ‪ .........‬هــذا وقــد جــرى ســؤال املدعــى عليــه عــن‬\n      ‫ســوابقه وهــي خمــس عشــرة ســابقة وكلهــا يف شــرب املســكرات‬\n      ‫ســوى ســابقة واحــدة وهــي مماثلــة لهــذه القضيــة فقــال إن الســوابق‬\n      ‫صحيحــة ونلــت اجلــزاء عليهــا هــذا وقــد جــرى ســؤاله عــن عمــره فقــال‬\n‫‪251‬‬\n\f‫إن عمــري ســبعني ســنة تقريبــا هــذا وقــد جــرى ســؤاله هــل هــو متــزوج‬\n‫ولديــه أوالد فقــال إننــي لســت متزوجــا وليــس لــدي أوالد وال أملــك منــزال‬\n‫وأســكن عنــد نســيبي زوج شــقيقتي هكــذا أفــاد لــذا وبنــاء علــى مــا‬\n‫ســبق مــن الدعــوى واإلجابــة وحيــث صــادق املدعــى عليــه علــى دعــوى‬\n‫املدعــي العــام ومؤاخــذة للمدعــى عليــه بإقــراره وحيــث إن فعــل املدعــى‬\n‫عليــه يعــد اســتخفافا بأمــوال الغيــر ونظــرا لكثــرة ســوابق املدعــى‬\n‫عليــه ولكبــر ســنه ممــا يــدل تأصــل الشــر يف نفســه وعــدم ارتداعــه يف‬\n‫العقوبــات الســابقة وحيــث إن املدعــى عليــه كبيــر يف الســن وليــس لديــه‬\n‫أوالد ونظــرا خلطــره علــى نفســه وعلــى املجتمــع وحيــث إن املدعــي باحلــق‬\n‫اخلــاص قــد قــرر تنازلــه عــن حقــه اخلــاص لــذا أوالً‪ :‬فقــد ثبــت لــدي تنــازل‬\n‫املدعــي باحلــق اخلــاص عــن حقــه اخلــاص جتــاه املدعــى عليــه‪ .‬ثانيـاً‪ :‬ثبــت‬\n‫لــدي إدانــة املدعــى عليــه مبــا نســب لــه بدعــوى املدعــي العــام وقــررت‬\n‫تعزيــره لقــاء ذلــك ولقــاء ســوابقه وذلــك بســجنه ســنة مــن تاريــخ إيقافــه‬\n‫وجلــده مئــة وعشــرين جلــدة مفرقــة علــى دفعتــن متســاويتني بــن كل‬\n‫دفعــة وأخــرى خمســة عشــر يومـ ًا ثالثـاً‪ :‬إيــداع املدعــى عليــه يف الرعايــة‬\n‫االجتماعيــة بعــد انتهــاء مــدة الســجن عليــه وحمايــة للمجتمــع مــن شــره‬\n‫وبجميــع مــا ذكــر قضيــت وبعــرض ذلــك علــى املدعــى عليــه قــرر عــدم‬\n‫القناعــة وطلــب االســتئناف بــدون الئحــة اعتراضيــة فأجبنــاه لذلــك‬\n‫أمــا املدعــي العــام فقــرر عــدم املعارضــة وعليــه جــرى التوقيــع وأقفلــت‬\n‫اجللســة يف متــام الســاعة التاســعة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/04/15‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n                      ‫بقــرار احملكمــة ومضمونــه املصادقــة علــى احلكــم ‪.‬‬\n\n                                                                                        ‫‪252‬‬\n\f               ‫رقم الصك ‪ 34188767 :‬تاريخه‪:‬‬\n          ‫‪1434/4/15‬هـ رقم الدعوى‪3411199:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪        34206074‬تاريخه‪1434/5/5 :‬هـ‬\n\n\n      ‫اعتــداء ‪ -‬اعتــداء علــى حيــوان ‪ -‬حــق عــام وحــق خــاص ‪ -‬تقريــر طبيــب‬\n      ‫بيطــري ‪ -‬إتــاف مــال الغيــر ‪ -‬انــكار املدعــى عليــه ‪ -‬تناقــض الشــهادة‬\n      ‫مــع الواقــع موجــب لردهــا ‪ -‬عــدم وجــود بينــة موصلــة ‪ -‬رد دعــوى املدعي‬\n                                                             ‫العــام ‪ -‬أخــذ تعهــد ‪.‬‬\n\n\n\n\n      ‫‪ -1‬حديــث عبــداهلل بــن عبــاس أن رســول اهلل صلــى اهلل عليــه وســلم قــال‪:‬‬\n      ‫« لــو يعطــى النــاس بدعواهــم الدعــى رجــال أمــوال قــوم ودماءهــم ‪ ،‬ولكن‬\n      ‫البينــة علــى املدعــي واليمــن علــى مــن أنكــر» أخرجــه البيهقــي وحســنه‬\n      ‫النــووي ‪ ،‬وقــال ابــن رجب‪»:‬وقــد اســتدل بــه أحمــد وأبــو عبيــد بــأن النبــي‬\n      ‫صلــى اهلل عليــه وســلم قــال‪ »:‬البينــة علــى املدعــي واليمــن علــى مــن‬\n      ‫أنكــر» وهــذا يــدل علــى أن هــذا اللفــظ عندهمــا صحيــح محتــج بــه»‬\n                                       ‫جامــع العلــوم واحلكــم شــرح احلديــث(‪.)33‬‬\n\n\n\n      ‫جــرى توجيــه االتهــام مــن قبــل االدعــاء العــام للمدعــى عليــه بقيامــه‬\n      ‫بصــدم جمــل عمــدا ممــا أحــدث بــه إصابــة وطلــب إثبــات مــا أســند إليــه‬\n      ‫واحلكــم عليــه بعقوبــة تعزيريــة حيــث تقــدم املدعــي اخلــاص مالــك اجلمــل‬\n      ‫بشــكوى ضــده بقيامــه بصــدم جملــه عمــدا ‪ -‬أنكــر املدعــى عليــه‬\n\n‫‪253‬‬\n\f‫الدعــوى وقــرر بــأن اجلمــل املشــار لــه يف الدعــوى قــد خالــط نياقــه فحاول‬\n‫إبعــاده بالســيارة باملشــي خلفــه وكان اجلمــل مقيــدا وقــد عثــر أثنــاء‬\n‫مشــيه خلفــه وقــد أخبــر الراعــي بذلــك وبقــي عنــد اجلمــل حتــى حضــر‬\n‫مالكــه ولــم يصــب بكســر وال غيــره ــ  مت طلــب البينــة مــن املدعــي‬\n‫العــام فأحضــر راعــي جمــال مالــك اجلمــل محــل الدعــوى وشــهد بقيــام‬\n‫املدعــى عليــه بصــدم جمــل كفيلــه مــن رجلهــا اليمنــى أثنــاء طــرده لــه‬\n‫عــن إبلــه فأصابهــا ولــم تتمكــن مــن املشــي بعدهــا حتــى اآلن ‪ ،‬فجــرى‬\n‫ســؤاله عــن الرجــل املصابــة فأكــد أنهــا اليمنــى ‪ ،‬قــرر املدعــى عليــه‬\n‫بــأن شــهادته غيــر صحيحــه وال يطعــن فيــه بشــيء ‪ -‬تبــن أن شــهادة‬\n‫الشــاهد تخالــف مــا ورد يف محضــر املعاينــة والتقريــر البيطــري مــن أن‬\n‫الرجــل املصابــة هــي اليســرى ‪ ،‬بســؤال املدعــي العــام هــل لديــه زيــادة‬\n‫بينــة فأجــاب بالنفــي ‪ ،‬وألن شــهادة الشــاهد مناقضــة للواقــع وهــذا‬\n‫مســقط ملقتضاهــا ‪ ،‬ولعــدم قيــام البينــة املوصلــة فقــد قَ ـ َـر َرت احملكمــة‬\n‫رد دعــوى املدعــي العــام إثبــات إدانــة املدعــى عليــه بصــدم جمــل عمــدا‬\n‫ولضعــف التهمــة بإقــراره بالســير خلــف اجلمــل وملــا تضمنــه محضــر‬\n‫املعاينــة والتقريــر البيطــري فقــد اكتفــت بأخــذ التعهــد عليــه ومبــا‬\n‫كمــت ‪ -‬قــرر املدعــى عليــه القناعــة بينمــا اعتــرض املدعــي‬        ‫تقــدم َح َ‬\n‫العــام بالئحــة ‪ -‬وقبــل رفــع احلكــم حملكمــة االســتئناف حضــر وكيــل‬\n‫املدعــي اخلــاص وادعــى علــى املدعــى عليــه بأنــه صــدم جمــل موكلــه‬\n‫عمــدا وعدوانــا ممــا أعاقــه عــن احلركــة متامــا وهــو يعــد مــن «مزايــن‬\n‫اإلبــل» وقيمتــه ثالثــة ماليــن ريــال ويطلــب إلزام املدعى عليــه بدفع قيمة‬\n‫اجلمــل ثالثــة ماليــن ريــال ‪ ،‬أنكــر املدعــي اخلــاص الدعــوى و طلــب مــن‬\n‫وكيــل املدعــي البينــة فقــرر بــأن بينتــه شــهادة الشــاهد املدونــة ومحضــر‬\n‫املعاينــة وتقريــر الطبيــب البيطــري وقيــام املدعــى عليــه بإرســال رجلــن‬\n                                                                                      ‫‪254‬‬\n\f      ‫إلقناعــه بالتنــازل عــن الدعــوى وأنــه نــادم علــى فعلتــه ‪ ،‬جــرى إفهــام‬\n      ‫وكيــل املدعــي اخلــاص بأنــه ســبق االطــاع علــى الشــهادة والتقريــر ومــا‬\n      ‫فيهــا مــن تناقــض وســؤاله ألديــه زيــادة بينــة فأجــاب بأنــه ليــس لديــه بينــة‬\n      ‫‪ -‬جــرى إفهــام وكيــل املدعــي اخلــاص بــأن ملوكلــه طلــب ميــن املدعــى‬\n      ‫عليــه فقــرر بأنــه يطلــب ميينــه وحلــف املدعــى عليــه اليمــن املطلوبــة ‪،‬‬\n      ‫عليــه وإلنــكار املدعــى عليــه ‪ ،‬ولعــدم قيــام البينــة ‪ ،‬وألن املدعــى عليــه‬\n      ‫حلــف اليمــن علــى نفــي دعــوى املدعــي ‪ ،‬لــذا فقــد قــررت احملكمــة‬\n      ‫صــرف النظــر عــن دعــوى املدعــي اخلــاص وأخلــت ســبيل املدعــى عليــه‬\n      ‫مــن هــذه الدعــوى فقــرر الطرفــان القناعــة باحلكــم فاكتســب احلكــم‬\n      ‫القطعيــة يف احلــق اخلــاص ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف يف‬\n                                                                          ‫احلــق العــام‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...............‬القاضــي يف احملكمــة‬\n      ‫العامــة بعرعــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بعرعــر برقــم ‪ 34200556‬وتاريــخ ‪ 1434/04/30‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 341069330‬وتاريــخ ‪ 1434/04/30‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافــق‪ 1434/07/22‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬‬\n      ‫وفيهــا حضــر ‪ ..............‬وادعــى قائــا بصفتــي مدعيــا عامــا يف دائــرة‬\n      ‫االدعــاء العــام بفــرع الهيئــة مبنطقــة احلــدود الشــمالية ادعــي علــى ‪/‬‬\n      ‫‪ ..................‬ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم ‪ ............‬يبلــغ‬\n      ‫مــن العمــر (‪ )55‬عــام متســبب يقيــم يف عرعــر لــم يوقف وربــط بالكفالة‬\n      ‫احلضوريــة املرفقــة لفــة ( ‪ ) 6‬فإنــه بتاريــخ ‪1434/3/9‬ه ـ تقــدم ملركــز‬\n\n‫‪255‬‬\n\f‫شــرطة ‪ .........‬املواطــن ‪ ............. /‬مبلغــا عــن تعــرض اجلمــل العائــد لــه‬\n‫للصــدم العمــد وإحلــاق الضــرر بــه والواقــع مبنطقــة صحراويــة تســمي‬\n‫( ‪ ) ......‬وباالنتقــال واملعاينــة تبــن املوقــع يبعــد ‪ 25‬كيلــو تقريبــا علــى‬\n‫طريــق ســكاكا وبالوصــول إليــه أتضــح أن موقــع املواطــن ‪................ /‬‬\n‫عبــارة عــن شــبك كبيــر لألبــل ويوجــد بيــت شــعر وخيمــة ووايــت مــاء‬\n‫ويحــده مــن ناحيــة الشــرق أبــل ‪ ......‬وعثــر علــى اجلمــل ولونــه واضــح فيــه‬\n‫أثــر ضربــة يف أســفل الفخــذ األيســر وكذلــك هنــاك ورم يف مفصــل‬\n‫القــدم اليســرى وعنــد حتريكــه لــم يســتطع الوقــوف على رجله اليســرى‬\n‫ويعــرج وحركتــه بطيئــة وصــدر بحــق اجلمــل التقريــر البيطــري املتضمــن‬\n‫( ان اجلمــل اوضــح اللــون ويبلــغ خمــس ســنوات ومصــاب بالرجــل اليســرى‬\n‫حيــث لوحــظ رفعــه لرجلــه اليســرى بصفــة مســتمرة مــع تــورم مفصــل‬\n‫الرســغ واخلــف ووجــد تــورم وكدمــات بعضــات الفخــذ االيســر وهــذه‬\n‫اصابــة معيقــة للجمــل عــن احلركــة الطبيعيــة ) وبضبــط شــهادة ‪.........‬‬\n‫شــهد بأنــه أثنــاء تواجــده مــع اإلبــل العائــدة لكفيلــه املدعــي ‪......... /‬‬\n‫حضــرت اإلبــل العائــدة للمتهــم ‪ ...... /‬إلــى أبــل ‪ ....... /‬وحضــر املتهــم‬\n‫بســيارته وقــام مبطــاردة اجلمــل وصدمــه بالســيارة مــن اخللــف وأصــاب‬\n‫رجلــه اليســرى وباســتجواب املتهــم ‪ /‬أفــاد بــأن جمــل املدعــو ‪........ /‬‬\n‫كان موجــود بالقــرب مــن األبــل العائــدة للمتهــم ‪ ......‬وانــه كان يريــد‬\n‫أن يبعــده عــن إبلــه واجلمــل كان ( مهجــور ) وأثنــاء أبعــاده للجمــل وذلــك‬\n‫بالســير خلفــه بالســيارة تعرقــل باملشــي لوحــده مــن دون أن يقــوم بصدمــه‬\n‫وأضــاف بــأن هنــاك موضــع أصابــه قدميــة بقــدم اجلمــل اليســرى مــن اثــر‬\n‫عضــة جمــل ســابقا وقــد انتهــى التحقيــق إلــى اتهــام ‪ .......... /‬بصــدم‬\n‫جمــل عمــدا ممــا أحــدث فيــه أصابــه وذلــك لألدلــة والقرائــن التاليــة ‪-1‬‬\n‫مــا جــاء يف أقوالــه املدونــة علــى الصفحــة رقــم ( ‪ )14‬مــن دفتــر التحقيــق‬\n                                                                                       ‫‪256‬‬\n\f      ‫املرفــق لفــة (‪ -2 )1‬مــا جــاء بشــهادة الشــاهد املدونــة علــى الصفحــة رقــم‬\n                                       ‫(‪ )15‬مــن دفتــر التحقيــق املرفــق لفــة (‪)1‬‬\n      ‫‪ -3‬مــا جــاء يف محضــر املعاينــة املدونــة علــى الصفحــة رقــم (‪ )16‬مــن‬\n      ‫دفتــر التحقيــق املرفــق لفــة (‪ -4 )1‬مــا جــاء يف التقريــر البيطــري املرفــق‬\n      ‫لفــة (‪ )11‬وبالبحــث عــن ســوابقه تبــن عــدم وجــود ســوابق وحيــث إن‬\n      ‫مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل محــرم‬\n      ‫ومعاقــب عليــه شــرعا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم‬\n      ‫عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره ( علمــا بــأن احلــق اخلــاص الزال‬\n      ‫قائمــا ) وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائــا‬\n      ‫مــا ذكــره املدعــي العــام مــن صدمــي بعيــر ‪ ........‬غيــر صحيــح والصحيح‬\n      ‫أن بعيــر ‪ .....‬قــد خالــط نياقــي فقمــت مبحاولــة ابعــاده بالســيارة باملشــي‬\n      ‫خلفــه وكان البعيــر مهجــور ( مقيــد اليديــن والرجلــن ) وقــد عثــر أثنــاء‬\n      ‫مشــي خلفــه وقــد أخبــرت الراعــي بذلــك وبقيــت عند البعير أنــا والراعي‬\n      ‫حتــى حضــر صاحــب البعيــر ولــم يصــب البعيــر مــن جراء ذلك ال بكســر‬\n      ‫وال غيــره هكــذا أجــاب وبســؤال املدعــي العــام البينــة علــى الدعــوى‬\n      ‫أجــاب قائــا ‪ :‬لــدي شــاهد وهــو حاضــر االن وأطلــب األذن بســماع مــا‬\n      ‫لديــه وعليــه حضــر ‪ ..........‬ســوداني اجلنســية مبوجــب اقامــة رقــم ‪..........‬‬\n      ‫وقــال معرفــا اننــي اعمــل راعــي عنــد ‪ ..........‬منــذ ســنتني وابلــغ مــن العمــر‬\n      ‫‪ 26‬عامــا واســكن بالقــرب مــن مدينــة عرعــر واملدعــي صاحــب اجلمــل‬\n      ‫هــو كفيلــي واملدعــى عليــه ال أعرفــه ســوى يف فتــرة الربيــع حيــث إنــه‬\n      ‫نــزل بإبلــه قريــب منــا ولــدى استشــهاده شــهد هلل قائــا ‪ :‬اشــهد هلل أن‬\n      ‫املدعــى عليــه هــذا احلاضــر قــام بســيارته نــوع ‪ ........‬بصــدم بعيــر كفيلــي‬\n      ‫مــن رجلــه اليمنــى وذلــك أثنــاء طــرده للبعيــر عــن أبلــه حيــث ســار خلفــه‬\n      ‫بســيارته حتــى صدمــه وأحــدث بــه اصابــة لــم يســتطع منهــا املشــي حتــى‬\n‫‪257‬‬\n\f‫األن هكــذا شــهد وبســؤال الشــاهد أيــن كانــت اصابــة البعيــر أجــاب‬\n‫قائــا برجلــه اليمنــى هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه‬\n‫أجــاب قائــا ‪ :‬مــا ذكــره الشــاهد غيــر صحيــح مطلقــا والصحيــح مــا‬\n‫ذكرتــه وبســؤال املدعــى عليــه هــل لديــه طعــن يف الشــاهد أجــاب قائــا‬\n‫‪ :‬أنــا ال اعرفــه مطلقــا هكــذا أجــاب ولتأمــل مــا ســبق ضبطــه جــرى‬\n‫رفــع اجللســة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/22‬ه ـ احلمــد هلل وحــده وبعــد ففــي‬\n‫يــوم األحــد املوافــق‪ 1434/07/23‬ه ـ افتتحــت اجللســة الســاعة ‪09.15‬‬\n‫وفيهــا حضــر املدعــي العــام وقــد احضــر معــه كال مــن ‪ ........‬ســعودي‬\n‫اجلنســية مبوجــب ســجل مدنــي رقــم ‪ .........‬و ‪ .........‬ســعودي اجلنســية‬\n‫مبوجــب ســجل مدنــي رقــم ‪ ..........‬وشــهد كل واحــد مبفــرده قائــا‬\n‫نشــهد هلل ان الشــاهد ‪ ........‬عــدل ثقــة هكــذا شــهدا ولتأمــل مــا جــرى‬\n‫رفــع اجللســة وعليــه حصــل التوقيــع ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/23‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/07/26‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 10.30‬وفيهــا حضــر املدعــي العــام وحضــر‬\n‫حلضــوره املدعــى عليــه واملثبــت هويتــه ســابقا وباالطــاع علــى شــهادة‬\n‫الشــاهد املدونــة ســابقا وجدتهــا تخالــف الواقــع حيــث إن شــكوى‬\n‫املشــتكي واحملاضــر املرفقــة اشــارت إن الرجــل املصابــة هــي اليســرى‬\n‫وقــد شــهد الشــاهد أنهــا اليمنــى كمــا جــرى منــا االطــاع علــى محضــر‬\n‫املعاينــة واالنتقــال واملــدون علــى صحيفــة رقــم (‪ )16‬مــن تعزيــر األحــوال‬\n‫األمنيــة املوحــد لفــة رقــم (‪ )1‬مــن طيــات املعاملــة واملــدون بــا تاريــخ وال‬\n‫يــوم وقــد نــص احلاجــه منــه ( اتضــح لــي أن هنــاك ضربــه يف أســفل الفخذ‬\n‫األيســر وكذلــك هنــاك ورم يف مفصــل القــدم اليســرى وال يســتطيع‬\n                                                                                       ‫‪258‬‬\n\f      ‫اجلمــل أن يطــأ علــى رجلــه اليســرى وعنــد حتريــك اجلمــل أتضــح لــي أن‬\n      ‫اجلمــل يعــرج مــن رجلــه اليســرى وحركتــه بطيئــة جــدا ) أ‪.‬ه ـ كمــا جرى‬\n      ‫منــا االطــاع علــى التقريــر البيطــري املرفــق علــى لفــة رقــم (‪ )11‬مــن‬\n      ‫طيــات املعاملــة واملــدون يــوم الثالثــاء املوافــق ‪1434/3/10‬ه ـ ونــص‬\n      ‫احلاجــه منــه ( فقــد تبــن إصابــة اجلمــل ( أوضــح اللــون ويبلــغ مــن العمــر‬\n      ‫خمــس ســنوات ) بالرجــل اليســرى حيــث لوحــظ رفــع اجلمــل لرجلــه‬\n      ‫اليســرى بصفــة مســتمرة مــع تــورم مفصــل الرســغ واخلــف ووجــود تــورم‬\n      ‫وكدمــات بعضــات الفخــذ األيســر هــذه االصابــة تعتبــر إصابــة معيقــة‬\n      ‫للجمــل عــن احلركــة الطبيعيــة ) أ‪.‬ه ـ وبســؤال املدعــي العــام هــل لديــة‬\n      ‫مزيــد بينــة أجــاب قائــا ‪ :‬ليــس لــدي ســوى مــا قدمتــه ‪ .‬فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى وأنــكار املدعــى عليــه ملــا جــاء فيهــا ولكــون شــهادة‬\n      ‫الشــاهد قــد جــاءت مناقضــة للواقــع وذلــك يســقطها ولكــون مــا قدمــه‬\n      ‫املدعــي العــام ال يعــد بينــة موصلــة لــذا كلــه فقــد رددت طلــب املدعــي‬\n      ‫العــام اثبــات ادانــة املدعــى عليــه ‪ ..........‬بصــدم جمــل عمــدا وحكمــت‬\n      ‫بعــدم ادانتــه بذلــك ونظــرا لتوجــه التهمــه الضعيفــة عليه بنــاء على اقراره‬\n      ‫بالســير خلــف اجلمــل وبنــاء علــى محضــر املعاينــة والتقريــر البيطــري‬\n      ‫فقــد اكتفيــت احلــق العــام بأخــذ التعهــد عليــه لقــاء ذلــك وبجميــع ذلــك‬\n      ‫حكمــت وبعــرض احلكــم علــى املدعــى عليــه قــرر قناعتــه بــه كمــا‬\n      ‫قــرر املدعــي العــام االعتــراض علــى احلكــم واكتفــى بالئحــة الدعــوى‬\n      ‫كالئحــة اعتراضيــة هــذا وقــد حضــر صاحــب احلــق اخلــاص ‪...........‬‬\n      ‫ســعودي اجلنســية مبوجــب ســجل مدنــي رقــم ‪ ..........‬بصفتــه وكيــا‬\n      ‫عــن ‪ .........‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل عرعــر برقــم‬\n      ‫‪ 34972098‬وتاريــخ ‪1434/7/22‬ه ـ والــذي لــه فيهــا حــق ( املطالبــة‬\n\n\n‫‪259‬‬\n\f‫وإقامــة الدعــاوى واملرافعــة واملدافعــة وســماع والــرد عليهــا واالقــرار‬\n‫واالنــكار والصلــح والتنــازل واإلبــراء وطلــب اليمــن ورده واالمتنــاع عنــه‬\n‫واحضــار الشــهود والبينــات والطعــن فيهــا وقبــول األحــكام واالعتراض‬\n                                             ‫عليهــا وطلــب االســتئناف ) أ‪ .‬ه ـ‬\n‫وادعــى قائــا ‪ :‬إن هــذا احلاضــر قــام بصــدم جمــل موكلــي عمــدا‬\n‫وعدوانــا ممــا أحــدث لــه إصابــة برجلــه اليســرى أعاقتــه عــن احلركــة‬\n‫متام ـ ًا وعطلــت منافعــه وهــو جمــل يعــد مــن مزايــن اإلبــل وقيمتــه هــي‬\n‫ثالثــة ماليــن ريــال لــذا أطلــب إلــزام املدعــى عليــه بدفــع ثالثــة ماليــن‬\n‫ريــال ملوكلــي وهــي قيمــة اجلمــل هــذه دعــواي وبعــرض ذلــك علــى املدعى‬\n‫عليــه احلاضــر انكــر مــا جــاء يف دعــوى املدعــي باحلــق اخلــاص جملــة‬\n‫وتفصيــا وبســؤال املدعــي باحلــق اخلــاص البينــة علــى الدعــوى اجــاب‬\n‫قائــا ‪ :‬بينتــي مــا جــاء يف شــهادة الشــاهد واملســموعة لــدى فضيلتكــم‬\n‫ســابقا وكذلــك مــا جــاء يف محضــر املعاينــة والتقريــر الطبــي وكلهــا‬\n‫مرفقــه لكــم كمــا أن املدعــى عليــه قــد أرســل لــي رجلــن إلقناعــي‬\n‫بالتنــازل عــن الدعــوى وأنــه نــادم علــى فعلتــه هكــذا قــرر هــذا وقــد‬\n‫ســبق منــا االطــاع علــى الشــهادة والتقريــر املذكــورة ولكــون مخالفــة‬\n‫للواقــع فقــد أفهمــت املدعــي باحلــق اخلــاص أن شــهادة الشــاهد ســاقطة‬\n‫ملخالفتهــا الواقــع وبســؤاله هــل لديــه مزيــد بينــة غيــر ذلــك أجــاب قائــا‬\n‫‪ :‬ال ليــس لــدي ســوى مــا قدمتــه ولقــول النبــي وصلــى اهلل عليــه وســلم‬\n‫( البينــة علــى املدعــي واليمــن علــى مــن أنكــر ) ولكــون مــا أقامــه‬\n‫املدعــي احلــق اخلــاص ال يقــوى علــى البــراءة األصليــة يف جانــب املدعــى‬\n‫عليــه لــذا ولكــون وكالــة احلاضــر تخولــه طلــب اليمــن فقــد افهمــت‬\n‫املدعــي باحلــق اخلــاص أن لــه ميــن املدعــى عليــه علــى نفــي دعــواه فأجــاب‬\n\n\n                                                                                     ‫‪260‬‬\n\f      ‫قائــا ‪ :‬اننــي اطلــب مهلــة حملاولــة احضــار الرجلــن الذيــن ســعيا بالصلــح‬\n      ‫بيننــا لســماع مــا لديهــم مــن شــهادة بذلــك وعليــه ولتمكــن املدعــي‬\n      ‫باحلــق اخلــاص مــن احضــار مــا لديــه جــرى رفــع اجللســة وتأجلــت حتــى يــوم‬\n      ‫الســبت املوافــق ‪1434/7/29‬ه ـ الســاعة العاشــرة والربــع صباحــا وعليــه‬\n      ‫حصــل التوقيــع ‪ ..‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                 ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/26‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1434/07/29‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة العاشــرة والربــع وفيهــا حضــر املدعــي باحلــق‬\n      ‫واملدعــي عليــه واملثبــت هويتهمــا ســابقا وبســؤال املدعــي وكالــة عمــا‬\n      ‫اســتمهل ألجلــه يف اجللســة املاضيــة اجــاب قائــا ‪ :‬إن مــن ســعى بالصلــح‬\n      ‫بيننــا هــم مــن جماعــة املدعــى عليــه وال اســتطيع احضارهــم واطلــب ميــن‬\n      ‫املدعــى عليــه علــى نفــي صدمــه للبعيــر واحداثــه االصابــات بــه وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه اســتعد اليمــن وقــد جــرى منــا تذكيــره مبغبــة‬\n      ‫ا‪:‬‬ ‫احللــف كاذبـ ًا فأصــر علــى بــذل اليمــن فأذنــت لــه فحلــف بــاهلل قائـ ً‬\n      ‫واهلل العظيــم عالــم الغيــب والشــهادة أننــي لــم أقــم بصــدم البعيــر العائــد‬\n      ‫ل‪ ..........‬ولــم أحــدث بــه اإلصابــات التــي يذكرهــا املدعــي ‪ .‬هكــذا‬\n      ‫أحلــف فبنــاء علــى مــا تقــدم مــن الدعــوى وأنــكار املدعــى عليــه ملــا جــاء‬\n      ‫فيهــا ولعــدم قيــام البينــة عليهــا وبــذل املدعــى عليــه اليمــن علــى نفــي‬\n      ‫دعــوى املدعــي لــذا فقــد صرفــت النطــر عــن طلــب املدعــى وكالــة إلــزام‬\n      ‫املدعــى عليــه بقيمــة بعيــر موكلــه لقــاء مــا يدعيــه مــن صدمــه واخليــت‬\n      ‫ســبيل املدعــى عليــه مــن الدعــوى باحلــق اخلــاص وبذلــك حكمــت و‬\n      ‫بعــرض احلكــم علــى املدعــي وكالــة واملدعــى عليــه قــرر كل واحــد‬\n      ‫منهمــا قناعتــه باحلكــم وعليــه تكــون هــذه الدعــوى منتهيــة يف احلــق‬\n\n\n‫‪261‬‬\n\f‫اخلــاص وحتــت نظــر محكمــة االســتئناف يف احلكــم العــام ‪ .‬وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                        ‫يف ‪1434 /7 /29‬هــ‪.‬‬\n\n\n\n\n                                                                                 ‫‪262‬‬\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                       ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n          ‫دعوى عامة ضد مدعى عليه مطلق السراح بإثبات‬\n  ‫‪5‬‬      ‫تعاطيه للحشيش املخدر واحلكم بعقوبته على ذلك‪،‬‬        ‫تعاطي‬    ‫‪1‬‬\n                    ‫واملدعى عليه يقر بالدعوى‬\n\n\n          ‫دعوى عامة بتعزير متهم بتعاطي الشمة وترويجها‬\n  ‫‪12‬‬      ‫حليازته لها بكمية كبيرة‪ ،‬وحيازة وترويج صور‬         ‫تعاطي‬    ‫‪2‬‬\n                         ‫ومقاطع جنسية‬\n\n\n            ‫دعوى عامة بإيقاع العقوبة احلدية والنظامية‪،‬‬\n  ‫‪19‬‬       ‫على املدعى عليه املتهم بشرب املسكر وتعاطي‬         ‫تعاطي‬    ‫‪3‬‬\n               ‫احلشيش‪ ،‬واملدعى عليه مريض نفسيا‬\n\n\n          ‫دعوى عامة باحلكم على املدعى عليه املقر بإثبات‬\n  ‫‪28‬‬      ‫تعاطيه احلشيش واحلبوب احملظورة‪ ،‬ومعاقبته على‬       ‫تعاطي‬    ‫‪4‬‬\n                              ‫ذلك  ‬\n\n\n          ‫دعوى عامة ضد املدعى عليه ذي السوابق بإثبات‬\n  ‫‪33‬‬     ‫تعاطيه احلبوب احملظورة ومعاقبته بالسجن واملنع من‬    ‫تعاطي‬    ‫‪5‬‬\n                              ‫السفر‬\n\n\n          ‫دعوى عامة مبعاقبة املدعى عليه على تعاطي حبوب‬\n  ‫‪41‬‬                                                         ‫تعاطي‬    ‫‪6‬‬\n             ‫محظورة (ترامادول) والشروع يف إهدائها‬\n\n\n           ‫دعوى عامة ضد مدعى عليهما بالعقوبة على حيازة‬\n  ‫‪52‬‬     ‫سيجارة حشيش وقارورة خمر وتعاطيه والتستر على  ‬       ‫تعاطي‬    ‫‪7‬‬\n               ‫مصدرهما وقيادة السيارة حتت تأثير ذلك‬\n\f‫الصفحة‬                      ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n            ‫دعوى عامة ضد مدعى عليهما بإثبات تعاطي‬\n  ‫‪60‬‬                                                        ‫تعاطي‬    ‫‪8‬‬\n            ‫احلشيش املخدر واحلبوب احملظورة وتسليمها‬\n\n\n          ‫دعوى عامة ضد ابن تقدم والده للجهة التنفيذية‬\n  ‫‪69‬‬       